(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c24"]=[{"id":"00008844","register_sub_id":"101","register_pk":"162287","name":"三条市水道局大崎浄水場量水器室","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうりょうすいきしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.61041369,"lng":138.99645568,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積3.9㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0353","desc":"配水池の西側に建つ。鉄筋コンクリート造平屋建、東西１．８ｍ南北２．０ｍである。外壁は洗出し仕上げで軒蛇腹を廻らし、出入口に庇を付ける。内部は漆喰塗りで中央背面寄りに量水器の土台を残す。簡素ながらも瀟洒な意匠で、景観に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008844"},{"id":"00012726","register_sub_id":"101","register_pk":"367629","name":"島道鉱泉主屋","kana":"しまみちこうせんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県糸魚川市大字島道字大沢獄3541-47","lat":37.08043389,"lng":138.02752278,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"15 － 495","desc":"市東部の山中にある温浴保養施設。主屋は敷地西端に北面して建つ。切妻造セメント瓦葺、総二階建で上下階とも北西二面に廊下を廻し、中央に中廊下を通して東西各2室を設ける。正面全面を掃出しとするなど開放的につくる。伝統的な湯治場の風情を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012726"},{"id":"00012727","register_sub_id":"101","register_pk":"367630","name":"島道鉱泉離れ","kana":"しまみちこうせんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県糸魚川市大字島道字大沢獄3541-47","lat":37.08043389,"lng":138.02752278,"geo_status":"db","era":"昭和16年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積41㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"15 － 496","desc":"主屋背面の西端に接続して建つ。南北棟の切妻造セメント瓦葺、外壁下見板張。上下階とも主屋とつながる廊下を東端に通し、1階に広間、2階に座敷2室を設ける。東面全面を掃出しとするなど開放的につくる。主屋とともに伝統的な湯治場の風情を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012727"},{"id":"00012513","register_sub_id":"101","register_pk":"367808","name":"すき焼八木店舗","kana":"すきやきやぎてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新発田市中央町三丁目甲1316-1他","lat":37.94836,"lng":139.325531,"geo_status":"geocoded","era":"昭和10年頃／昭和15年増築、昭和49年･平成18年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積104㎡、塀付","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0487","desc":"市中心部の街路に北面して建つ商店。切妻造桟瓦葺の総二階建で、正面西半を後退させて玄関を設け、東半に店舗、茶の間、仏間の三室、二階に和室4室を配する。銘木を用いた座敷飾や縁側の色硝子など、戦前の都市部における店舗兼住宅の様相をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012513"},{"id":"00010430","register_sub_id":"101","register_pk":"199389","name":"清廣館本館","kana":"せいこうかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県阿賀野市出湯字寺山802子他","lat":37.817835,"lng":139.30075,"geo_status":"db","era":"昭和3頃／昭和40頃・昭和50・平成20改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造3階建、瓦葺、建築面積257㎡","structure_material":"木造3階建","registered":"2015.03.26(平成27.03.26)","register_no":"15 － 0399","desc":"出湯温泉の温泉旅館。木造三階建、入母屋造の大規模な建物でＬ字形平面を持つ。客室の内部は部屋毎に床柱などの材種を変え、銘木を多用した数寄屋風の意匠となる。上階は軒を出桁造とし、ガラス窓を並べて手摺を設け、湯治宿に相応しく風情ある外観を見せる","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010430"},{"id":"00011107","register_sub_id":"101","register_pk":"205214","name":"瀬賀惣一郎商店倉庫","kana":"せがそういちろうしょうてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市塩谷1234","lat":38.156398,"lng":139.414555,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積24㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0449","desc":"店舗兼主屋の北に並び建つ。鉄筋コンクリート造二階建で主屋兼店舗側に開口部を開く。外壁は人造石洗出仕上で石造風の目地を入れ、妻壁はやや簡略化したペディメント風につくり、窓下部にアールデコ風の装飾を付けるなど当地域に珍しい近代的な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011107"},{"id":"00011106","register_sub_id":"101","register_pk":"205213","name":"瀬賀惣一郎商店店舗兼主屋","kana":"せがそういちろうしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市塩谷1234","lat":38.156301,"lng":139.414592,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積279㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0448","desc":"塩谷集落の南、通りに西面して建つ。木造二階建桟瓦葺で通りに妻を向け、正面に下屋を付すなど当地域共通の特徴を示すが、屋根を入母屋造とし、二階に建具を並べるなど発展した形態を見せる。内部吹抜の梁や、上質なしつらえの座敷の造作が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011106"},{"id":"00005114","register_sub_id":"101","register_pk":"106104","name":"早撰堂菓子店主屋","kana":"そうせんどうかしてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町1510","lat":38.22462979,"lng":139.47848069,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0191","desc":"村上城下の目抜き通りに東面して建つ。桁行３間，梁間１０間の規模で，南北棟，切妻造，桟瓦葺の２階建町家。内部は１階にミセ，チャノマ等を並べ，２階はチャノマ上部吹抜けの前後にマエニカイ等を配する。棟梁は増田寅吉。通りの歴史的景観要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005114"},{"id":"00004341","register_sub_id":"101","register_pk":"105331","name":"髙橋あめや主屋","kana":"たかはしあめやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市南本町3-81","lat":37.10159539,"lng":138.2451218,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積109㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"15 － 0172","desc":"北国街道に面する切妻造，平入の町家で，正面に雁木を設け，その上方に２階の格子窓を見せる。１階内部は土間床のミセを正面に構え，奥に事務室が続き，２階は通りに面して座敷２室を並べる。雪国における商家の表構えをよく残す町家建築として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004341"},{"id":"00011099","register_sub_id":"101","register_pk":"205206","name":"つるがや店舗兼主屋","kana":"つるがやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県三条市本町四丁目601","lat":37.629671,"lng":138.952732,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0441","desc":"三条の中心市街に所在する。通りに南面して建ち、妻入とする。正面にせがい造の入母屋屋根を見せ、当地の町家の特色を良く示す。内部は手前に店舗、奥に通り土間を通して吹き抜けのチャノマと、ネマを配する。二階には丁寧な造作になる座敷を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011099"},{"id":"00001595","register_sub_id":"101","register_pk":"102585","name":"鍋茶屋応接室棟","kana":"なべぢゃやおうせつしつとう","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92385017,"lng":139.04607393,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、瓦葺、建築面積48㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0067","desc":"主屋の南側に位置する。１階はＲＣ造で，外壁石張の洋間には矩形上げ下げ窓とステンドグラスの入った２連の尖頭アーチ型窓が付けられる。精緻な細工を凝らした漆喰天井や装飾照明が，内部空間に華美な趣を与える。２，３階は木造の和風。設計施工は清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001595"},{"id":"00001597","register_sub_id":"101","register_pk":"102587","name":"鍋茶屋表門及び外塀","kana":"なべぢゃやおもてもんおよびそとべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92412972,"lng":139.04596227,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、間口2.6m、外塀延長35m","structure_material":"鉄筋コンクリート造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0069","desc":"敷地西面の通称鍋茶屋通りに面して建つ。表門は片流れ桟瓦葺。外塀には，表門と同様に，腰壁石積にＲＣ造壁面が載り，上下の接続部をリシン仕上げとする。縦格子の開口部によって，門と壁の意匠的統一性がさらに図られる。離れ座敷と共に清水組による施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001597"},{"id":"00001594","register_sub_id":"101","register_pk":"102584","name":"鍋茶屋主屋","kana":"なべぢゃやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92416238,"lng":139.04626969,"geo_status":"db","era":"明治43／昭和12増改築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造3階建、瓦葺、建築面積1251㎡","structure_material":"木造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0066","desc":"鍋茶屋は幕末期創業と伝わる料亭である。主屋は概ねＨ字型に構成され，南側の東西棟部分以外が昭和１２年に清水組によって増築される。１階から３階に向かって規模が大きくなる各室では，欄間・棚等に多様な意匠が施され，近代和風の粋が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001594"},{"id":"00001598","register_sub_id":"101","register_pk":"102588","name":"鍋茶屋土蔵","kana":"なべぢゃやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92401749,"lng":139.04633696,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積43㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0070","desc":"主屋と並び，建物群に埋め尽くされた敷地の東部に位置する。新建材で覆われる外部東面は，妻面と開口部に土蔵造りの痕跡を残す。２階中央部の棟木と母屋を支える大梁に自然木の極端な曲り材を用い，内部空間の見所を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001598"},{"id":"00001596","register_sub_id":"101","register_pk":"102586","name":"鍋茶屋離れ座敷","kana":"なべぢゃやはなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.9238211,"lng":139.04622239,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0068","desc":"敷地の南東端に位置する。木造２階建，瓦葺。１階には座敷の他に茶室，２階は二間続きの座敷を配し，全体的に数寄屋風の意匠でまとめられる。道路を望む広い開口部及び細い水平材と束の組合わせからなる繊細な妻飾りが，街路の景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001596"},{"id":"00001600","register_sub_id":"101","register_pk":"102590","name":"鍋茶屋離れ土蔵","kana":"なべぢゃやはなれどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92427379,"lng":139.04603802,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0072","desc":"敷地の北西端，主屋と中庭を挟んで建つ。現在，食堂として使われる。土蔵造２階建，切妻桟瓦葺。腰の海鼠壁の上を漆喰塗りとし，１・２階に形式・意匠を同じくする観音開き扉を配す。広大な敷地を持つ鍋茶屋正面の隅部を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001600"},{"id":"00001599","register_sub_id":"101","register_pk":"102589","name":"鍋茶屋煉瓦蔵","kana":"なべぢゃやれんがぞう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92394921,"lng":139.04632434,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積63㎡","structure_material":"煉瓦造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0071","desc":"敷地東部で，離れ座敷と土蔵に挟まれて建つ。煉瓦造平屋建で，壁面は小口積で作られる。片流れ桟瓦葺の屋根の上に，防火・目隠用の煉瓦壁を立ち上げる。土蔵と同じく外壁を介せずに東堀通りに面し，主屋・離れ座敷と共に街路に多様な景観をもたらしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001599"},{"id":"00013702","register_sub_id":"101","register_pk":"505227","name":"長谷川家住宅双子蔵","kana":"はせがわけじゅうたくふたごくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新発田市大栄町七丁目甲317-1","lat":37.94631944,"lng":139.32765833,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積105㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 546","desc":"市の中心部に位置。南北二棟の土蔵全体を桟瓦葺の置屋根で覆い一体とする。土蔵はいずれも東西棟で二階建切妻造。東面の開戸を掛子塗とするなど見応えがある。小屋組は棟木で断面の太い垂木を受ける。二蔵を大屋根で覆う特徴的な外観が地域の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013702"},{"id":"00011917","register_sub_id":"101","register_pk":"210924","name":"平久呉服店店舗兼主屋","kana":"ひらきゅうごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新発田市御幸町一丁目甲824-1他","lat":37.94817,"lng":139.323293,"geo_status":"db","era":"昭和10年頃／昭和57年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-459","desc":"中心市街地の御幸町の角地に南面する。一階には通りに面して矩折れに土間を設け、ミセや茶の間、和室を配し、二階には床の間・床脇を備えた座敷や数寄屋風の下地窓のある和室を設け、接客にあてた。採光のため廻らされたガラス窓が外観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011917"},{"id":"00003078","register_sub_id":"101","register_pk":"104068","name":"益甚酒店店舗","kana":"ますじんさけてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市大町194","lat":38.22421861,"lng":139.47866154,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0139","desc":"旧村上城下町人地の中心的通りに西面して建つ。南北棟，切妻造，桟瓦葺，平入の２階建店舗で，間口は５間半とし，１階店舗の奥に平屋建の１２畳と通り土間が付属し，２階は６畳６畳８畳の３室が並ぶ。たちの高いつくりが昭和初期町家の特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003078"},{"id":"00006124","register_sub_id":"101","register_pk":"107108","name":"山上染物店主屋","kana":"やまがみそめものてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市肴町1985","lat":38.223911,"lng":139.46994,"geo_status":"db","era":"明治初期／昭和55・平成17改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"15 － 0254","desc":"県道沿いに北面して建つ。桁行４間，梁間７間規模で，木造２階建，切妻造，桟瓦葺。１階前方を店とし，東端に土間を通し，土間沿いに茶の間・台所を並べ，２階にオモテニカイ等を配する。もとは石置屋根で緩い屋根勾配を特徴とし，街道沿いの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006124"},{"id":"00013979","register_sub_id":"101","register_pk":"508239","name":"山重本店店舗","kana":"やまじゅうほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県加茂市仲町236","lat":37.65761667,"lng":139.05505,"geo_status":"db","era":"明治後期／昭和38年・同40年増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺一部鉄板葺、建築面積523㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0560","desc":"加茂山北麓から市街を見下ろす料亭で、斜面を利用して上段の店舗棟と下段の喫茶棟の各二階建が接続する。店舗上階の長細い大広間は南と北に縁が通り、元は襖で小間に仕切って使った。店舗棟西端に広間、喫茶棟に小間の客室を配す。近代料亭の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013979"},{"id":"00008660","register_sub_id":"101","register_pk":"149381","name":"吉乃川酒造常倉","kana":"よしのがわしゅぞうじょうくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋4-2247","lat":37.41672118,"lng":138.84103699,"geo_status":"db","era":"大正12年／昭和3年改修","year":1923,"year_source":"converted","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積546㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0333","desc":"県道の東側に南北棟で建つ倉庫。桁行34ｍ梁間16ｍの鉄筋コンクリート造、小屋は鉄骨トラス組とする。切妻造で、ＲＣ造天井スラブ上に鉄板を張り、2ヶ所に越屋根を載せる。2階の部屋はトラス陸梁から鉄筋で吊される。醸造業の近代化を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008660"},{"id":"00011916","register_sub_id":"101","register_pk":"210923","name":"吉原写真館","kana":"よしはらしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新発田市大手町二丁目1286","lat":37.951417,"lng":139.321401,"geo_status":"db","era":"昭和11年／昭和47年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造3階建、瓦葺、建築面積175㎡","structure_material":"木造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-458","desc":"大手町に南面する。木造三階建で、二階には傾斜した大窓より自然光を取り入れたスタジオや床の間・床脇のある座敷がよく残る。外壁をモルタル仕上げとし、一階正面腰壁のスクラッチタイル貼や水平性を強調した庇や丸窓など、幾何学的な意匠を特徴とする外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011916"},{"id":"00009259","register_sub_id":"101","register_pk":"194052","name":"嵐渓荘緑風館","kana":"らんけいそうりょくふうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市長野1680-1","lat":37.52675255,"lng":139.11817141,"geo_status":"db","era":"昭和8年頃／昭和30年頃移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建、瓦葺、建築面積140㎡、望楼付","structure_material":"木造3階建","registered":"2012.08.13(平成24.08.13)","register_no":"15 － 0374","desc":"山間部の川沿いに建つ。木造三階建、建築面積一四〇平方メートル、入母屋造鉄板葺で、頂部に望楼を載せる。外壁は簓子下見板張とし、各階に庇を廻らせる。内部客室は部屋ごとに座敷飾りの意匠を違え、瀟洒なつくりとする。風情ある一軒宿の温泉旅館である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009259"},{"id":"00004742","register_sub_id":"101","register_pk":"105732","name":"凌雲閣松之山ホテル本館","kana":"りょううんかくまつのやまほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県十日町市松之山天水越81","lat":37.06229796,"lng":138.59965614,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、瓦葺、建築面積514㎡","structure_material":"木造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0185","desc":"山間部の高台に建つ温泉旅館の本館。３階建，入母屋造，桟瓦葺で正面中央に車寄せ玄関を突出させ，大屋根に千鳥破風を付す。客室をはじめ客溜りや階段室も銘木を使い，座敷飾りや欄間，天井造作など手の込んだ細工になる。内外とも風格ある佇まいをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004742"},{"id":"00007345","register_sub_id":"101","register_pk":"108327","name":"料亭宇喜世北門","kana":"りょうていうきよきたもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市仲町三丁目字下田端169他","lat":37.11194514,"lng":138.24259662,"geo_status":"db","era":"昭和前期／昭和26頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、茅葺、間口4.3m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"15 － 0309","desc":"本館玄関の正面、大門通りに面して建つ。茅葺屋根をもつ間口４．３ｍの腕木門。柱や楣、束等は八角断面で、名栗仕上げとする。腕木や桁は角材。軒には磨き丸太の半割を並べる。扉は両開板戸。茅葺の落ち着いた佇まいになり、料亭の表構えを特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007345"},{"id":"00007346","register_sub_id":"101","register_pk":"108328","name":"料亭宇喜世東門","kana":"りょうていうきよひがしもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県上越市仲町三丁目字下田端169他","lat":37.111897,"lng":138.242905,"geo_status":"db","era":"昭和26頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造、銅板葺、間口2.9m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"15 － 0310","desc":"本館東端の北側、仲町通りに東面して建つ。南北棟の銅板葺切妻屋根が載る間口２．９ｍの腕木門。柱や楣、棟木、桁などに磨き丸太を用い、軒は一軒疎垂木。両開板戸を吊る。軽快な意匠になり、主屋や北門とともに街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007346"},{"id":"00007344","register_sub_id":"101","register_pk":"108326","name":"料亭宇喜世本館","kana":"りょうていうきよほんかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市仲町三丁目字下田端169他","lat":37.11180583,"lng":138.24258241,"geo_status":"db","era":"明治中期／昭和前期改修・昭和13増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部3階建、瓦葺一部鉄板葺、建築面積550㎡","structure_material":"木造2階一部3階建","registered":"2008.10.23(平成20.10.23)","register_no":"15 － 0308","desc":"木造２階一部３階建の桟瓦葺一部鉄板葺、東西３７ｍ南北１４ｍで、北面西端に突出部を設けるＬ字型の平面になる。北面中央西寄りには唐破風造屋根の玄関を付ける。２階の１５３畳に及ぶ大広間や、部屋ごとに意匠を違える３階客間などをもつ。近代料亭建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007344"},{"id":"00011930","register_sub_id":"101","register_pk":"210937","name":"料亭南都屋","kana":"りょうていなんとや","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県胎内市本町2858他","lat":38.051832,"lng":139.402779,"geo_status":"db","era":"昭和4年／平成15年曳家","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積226㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-472","desc":"木造二階建、入母屋造、桟瓦葺で、正面に入母屋造の玄関と右側に切妻造の前の間を張り出す。内部は、一階に三室続きの中の間や応接室を配し、二階は五九畳半の大広間とする。小屋組は洋小屋であり、造作材に米松や地松の良材を用い洗練された意匠の料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011930"},{"id":"00011676","register_sub_id":"101","register_pk":"210692","name":"荒町庵（旧米田楼）","kana":"あらまちいおり（きゅうよねだろう）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県南砺市城端字西下町185","lat":36.516331,"lng":136.902275,"geo_status":"db","era":"明治後期／昭和2年・同22年・平成28年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0132","desc":"城端中心地に建つ。当初は米田楼と称する料理屋であった。東西方向に長い敷地に建つ木造二階建、切妻造平入、外壁下見板張で、東面街路側を正面とする。屋根は施釉瓦。正面二階には縁を設けて曳山を眺める空間とする。城端の賑わいを今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011676"},{"id":"00000760","register_sub_id":"101","register_pk":"101750","name":"井波屋仏壇店","kana":"いなみやぶつだんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県高岡市守山町37-1","lat":36.74697948,"lng":137.01063186,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造２階建，瓦葺，建築面積96㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"16 － 0044","desc":"間口３間，奥行６間半の小規模な店舗で，内部は過半を土間とし背後に部屋をおく。２階は前１間にテラスを設け，中央部は吹き抜けとする。正面意匠は，鋳物製の唐草模様で飾る大きなアーチ窓を置く独特のデザインになり，明治後期の店舗として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000760"},{"id":"00002031","register_sub_id":"101","register_pk":"103021","name":"小沢家住宅店蔵","kana":"おざわけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市荒町1618","lat":36.76617566,"lng":137.3374873,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0058","desc":"小沢家は明治期より呉服商を営んだ商家である。店蔵は桁行６間・梁間３間・総２階建，切妻造・桟瓦葺で，三代目万治の明治後期に建てられた。黒漆喰塗で観音開扉をもつ重厚な土蔵造で，棟の剣形雪割瓦や鯱，正面の起り屋根の下屋など，地方色も備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002031"},{"id":"00002028","register_sub_id":"101","register_pk":"103018","name":"城戸家住宅主屋","kana":"きどけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1862","lat":36.76332659,"lng":137.3355953,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積191㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0055","desc":"旧北陸街道沿いに建ち，江戸後期より味噌醤油の醸造業を営んできた商家。主屋は慶応大火後，明治初期に再建。２階建，切妻造，桟瓦葺，平入の形式で，全体に良質の材や銘木を用いる。内部では１階前面に板敷でつくりつけの帳場を持つミセ構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002028"},{"id":"00002027","register_sub_id":"101","register_pk":"103017","name":"清都酒造場主屋","kana":"きよとしゅぞうじょうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市京町12-12","lat":36.75617282,"lng":137.01371599,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積176㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0054","desc":"旧氷見街道沿いに建つ商家で，清都家が以前からの造り酒屋を購入したのは明治３９年。銘柄「勝駒」は高岡市民に親しまれている。主屋は明治２０年頃の建設と伝え，２階建，切妻造，桟瓦葺，平入で，登り梁や袖壁及び厚板目板打の庇など伝統的な形式である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002027"},{"id":"00001411","register_sub_id":"101","register_pk":"102401","name":"小杉町民展示館（旧小杉貯金銀行本店）","kana":"こすぎちょうみんてんじかん（きゅうこすぎちょきんぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市戸破4286-1","lat":36.72226155,"lng":137.09927992,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"16 － 0049","desc":"地域の有力者の共同出資によって創業した，小杉町の中心的銀行の本館。内部改装の後，現在歴史資料展示館として利用されている。黒塗漆喰壁の土蔵造で，窓には金属性の防火扉が取り付けられている。内部には随所に明治後期の洋風意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001411"},{"id":"00010134","register_sub_id":"101","register_pk":"197967","name":"松風樓一の蔵","kana":"しょうふうろういちのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市福光字川原7471-15","lat":36.560486,"lng":136.875171,"geo_status":"db","era":"昭和前期／昭和26頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0098","desc":"敷地北辺西寄りに建つ、土蔵造二階建、切妻造で、置屋根式の桟瓦葺とする。基礎はコンクリート造とし、外壁は漆喰塗で、北面は竪板張とする。南側に戸前の下屋を付け、戸口の扉枠は鳥居形で黒漆喰塗とし、鉄製両開扉を吊り込む。小屋組は垂木小屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010134"},{"id":"00010133","register_sub_id":"101","register_pk":"197966","name":"松風樓西棟","kana":"しょうふうろうにしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県南砺市福光字川原7471-15他","lat":36.560372,"lng":136.875046,"geo_status":"db","era":"明治33／昭和26頃移築・昭和33頃改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0097","desc":"敷地の西寄りに東棟から中庭を介して建つ木造二階建、正面入母屋造で、北に平屋建の浴室、便所が接続する。一階に仏間と次の間を設け、東棟への回廊は南半を土間とし、中間に中庭に通じる戸口を設ける。二階軒の漆喰蛇腹など、当地の茶屋建築の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010133"},{"id":"00010135","register_sub_id":"101","register_pk":"197968","name":"松風樓二の蔵","kana":"しょうふうろうにのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市福光字川原7471-15","lat":36.560522,"lng":136.875103,"geo_status":"db","era":"昭和前期／昭和26頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0099","desc":"敷地の北西角に一の蔵と並んで建つ。土蔵造二階建、切妻造で、置屋根式の桟瓦葺とする。基礎はコンクリート造とし、外壁は漆喰塗で、北面と西面は竪板張とする。南側に戸前の下屋を付け、一の蔵の戸前から入る。戸口は片引土戸とする。角地の景観を整える蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010135"},{"id":"00010132","register_sub_id":"101","register_pk":"197965","name":"松風樓東棟","kana":"しょうふうろうひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県南砺市福光字川原7471-8","lat":36.56024,"lng":136.875256,"geo_status":"db","era":"明治33／昭和前期改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積449㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0096","desc":"小矢部川の西岸に位置する料理旅館。木造二階建、寄棟造の本館の北に、中庭を介して二階建、寄棟造の離れを増築している。本館一階東側の厨房上の二階を広間とする他は六畳から十畳の客室とする。各室毎に趣向を凝らした造作をもつ近代数寄屋建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010132"},{"id":"00012522","register_sub_id":"101","register_pk":"367817","name":"富山電気ビルディング新館","kana":"とやまでんきびるでぃんぐしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県富山市桜橋通り3","lat":36.696598,"lng":137.216766,"geo_status":"geocoded","era":"昭和31年／昭和38年・同40年増築","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄筋コンクリート造6階地下1階建、建築面積1156㎡","structure_material":"鉄筋コンクリート造6階地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"16 － 0142","desc":"北面道路沿いに建つ、本館とＬ字形をなす鉄筋コンクリート造６階地下１階建のビル。本館と同じ富永譲吉の設計による全体にシンプルでモダンな意匠が特徴で、本館同様、柱形や窓など機能上の必須要素のみを巧みに構成した外観は増築の違和感を感じさせない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012522"},{"id":"00012521","register_sub_id":"101","register_pk":"367816","name":"富山電気ビルディング本館","kana":"とやまでんきびるでぃんぐほんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県富山市桜橋通り3","lat":36.696598,"lng":137.216766,"geo_status":"geocoded","era":"昭和11年／昭和32年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造5階地下1階建、建築面積2087㎡、塔屋付","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"16 － 0141","desc":"富山駅と市街地中心部を結ぶ幹線道路沿いに西面して建つ。鉄筋コンクリート造５階地下１階建で、外観は柱形を並べて垂直性を強調し、中央部を高くして大きなバルコニーをつくり出し、両端に丸窓を設けるなど表情に変化をつける。県内初の本格的オフィスビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012521"},{"id":"00009750","register_sub_id":"101","register_pk":"195579","name":"北陸銀行本店","kana":"ほくりくぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県富山市堤町通り1-2-9他","lat":36.68909194,"lng":137.21790083,"geo_status":"db","era":"昭和36／昭和48増築","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄骨鉄筋コンクリート造6階地下2階建、建築面積2864㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造6階地下2階建","registered":"2013.12.24(平成25.12.24)","register_no":"16 － 0093","desc":"鉄骨鉄筋コンクリート造六階地下二階建、三階建塔屋付。六層分の柱列を表し、柱間に小割の石を貼詰める。重厚な構造ながら、軽快な外観を構成し、一階では表通りから裏通りの商店街に通じるコロネードを通す。富山市の戦後復興期を象徴する大型事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009750"},{"id":"00002625","register_sub_id":"101","register_pk":"103615","name":"牧田組本社（旧南島商行本店）","kana":"まきたぐみほんしゃ（きゅうみなみじましょうこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県射水市庄西町1-18-33","lat":36.7890097,"lng":137.06783222,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、銅板葺、建築面積81㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"16 － 0066","desc":"富山湾に注ぐ庄川の河口に築かれたオフィスビル。木造躯体に褐色煉瓦を貼り，腰，隅柱，蛇腹などに花崗岩を用いる。前方に張り出し重量感のある石造柱に挟まれた入口を中心に，上げ下げ窓を左右対称に配する外観とする。伏木港における海運の近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002625"},{"id":"00013985","register_sub_id":"101","register_pk":"508245","name":"みなとがわ倉庫","kana":"みなとがわそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県氷見市朝日本町907","lat":36.85281944,"lng":136.98604722,"geo_status":"db","era":"大正後期／昭和中期・平成28年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造平屋建、瓦葺、面積486㎡","structure_material":"土蔵造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0157","desc":"氷見市街地の湊川左岸、旧藺製品倉庫の南に北面して建つ長大な土蔵。切妻造桟瓦葺、外壁は下見板張。北面に梁間の大きい戸前を設け東端を荷揚場とする。内部は桁行に六室を並べ、各室北側に額縁黒漆喰塗戸口、南面に高窓を設ける。湊川水運の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013985"},{"id":"00008271","register_sub_id":"101","register_pk":"133913","name":"若井家住宅主屋（旧中越銀行）","kana":"わかいけじゅうたくしゅおく（きゅうちゅうえつぎんこう）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市川原町65-6","lat":36.75033358,"lng":137.0097681,"geo_status":"db","era":"明治35年／大正7年移築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"16 － 0090","desc":"道路に東面する敷地中央に位置する。入母屋造妻入桟瓦葺で正面に深い下屋を出す。桁行１５ｍ梁間９．２ｍの木造２階建。漆喰塗で塗り込め、２階正面には掛子塗の両扉を吊る開口を三ヶ所穿つ。下屋正面両端には洋風の石柱を建てる。近代地方銀行の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008271"},{"id":"00011284","register_sub_id":"101","register_pk":"209120","name":"粟津演舞場","kana":"あわづえんぶじょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県小松市井口町ヘ10-1他","lat":36.33346,"lng":136.447175,"geo_status":"db","era":"昭和8頃／昭和18頃・平成26改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0261","desc":"粟津温泉街の中心部に位置する劇場建築。昭和八年粟津温泉で開催された全国旅館組合総会の会場として建設された。正面に入母屋造の大屋根妻面と左右突出部の切妻破風を並べ、中央に起り屋根の玄関を付すなど装飾的に見せる。当時の温泉街の賑わいを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011284"},{"id":"00010584","register_sub_id":"101","register_pk":"201158","name":"石黒商店店舗兼主屋","kana":"いしぐろしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市十間町53他","lat":36.570524,"lng":136.657963,"geo_status":"db","era":"昭和11年頃／昭和41年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"17－0249","desc":"美術商の店舗兼用住宅として建築された町家。建ちの高い一階正面は、瓦葺の庇の下に銅板葺の小庇を設けて立面を整える。せがい造の軒や、大屋根に付く採光用の越屋根、木部の弁柄塗と黒漆喰壁のコントラストにより華やかな外観を呈し、街並み景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010584"},{"id":"00005432","register_sub_id":"101","register_pk":"106420","name":"角島家住宅店舗及び主屋","kana":"かどしまけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市安江町5-14","lat":36.5760305,"lng":136.65604592,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造3階建、鋼板葺一部瓦葺、建築面積60㎡","structure_material":"木造3階建","registered":"2006.03.27(平成18.03.27)","register_no":"17 － 0152","desc":"北側道路に接して建ち，桁行９．５ｍ，梁間７．６ｍの規模で，木造３階建，切妻造，鋼板葺一部桟瓦葺で，正面１階をタイル貼り，２階以上を銅板張りとし，東端にモルタル塗の外壁を立ち上げる。１階を店舗，２階以上を住宅とし，正面を洋風意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005432"},{"id":"00004356","register_sub_id":"101","register_pk":"105346","name":"北島屋茶店主屋","kana":"きたじまやさてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市一本杉町54","lat":37.04803376,"lng":136.96138217,"geo_status":"db","era":"明治37頃／昭和8改造","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0122","desc":"住宅として建てられ昭和８年茶舗となる。間口４間奥行６間半，切妻造，桟瓦葺で，１階東に通り庭，西に表からミセの間，居室を１列に並べ，２階には表裏にそれぞれ次の間付座敷をとる。大火以前に遡る稀少な建物で，七尾中心地の歴史的景観に欠かせない町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004356"},{"id":"00004346","register_sub_id":"101","register_pk":"105336","name":"北中家住宅主屋","kana":"きたなかけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市泉二丁目491","lat":36.547143,"lng":136.64090612,"geo_status":"db","era":"江戸末期／大正初期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造及び土蔵造2階建、瓦葺、建築面積241㎡","structure_material":"木造及び土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0112","desc":"市内南部，旧北国街道に東面する味噌・醤油製造販売を営む町家。間口９間奥行９間，２階建，平入，桟瓦葺で，正面のほぼ全面に格子をはめ，２階両端に袖壁を付ける。１階南東隅に座敷蔵を取り込み，木部弁柄漆塗り，色土壁として内外とも質の高い造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004346"},{"id":"00004350","register_sub_id":"101","register_pk":"105340","name":"旧石川銀行橋場支店","kana":"きゅういしかわぎんこうはしばしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市尾張町1-7-10","lat":36.57084281,"lng":136.66370819,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積101㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0116","desc":"浅野川大橋南方の交差点に面した不整形の敷地に建つ。清水組の設計施工で，外観はネオルネサンス式を基調とし，胴蛇腹で上下にほぼ１対２に分割し，出入口はイオニア式の片蓋柱で飾る。曲面で構成される変化のある立面をもち，ランドマークとして目立つ建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004350"},{"id":"00014353","register_sub_id":"101","register_pk":"511342","name":"旧石川県繊維会館","kana":"きゅういしかわけんせんいかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県金沢市西町三番丁16","lat":36.569725,"lng":136.65609167,"geo_status":"db","era":"昭和27年／同59年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、瓦葺、建築面積525㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2022.10.31(令和4.10.31)","register_no":"17 - 0308","desc":"金沢城北西の市街地にある繊維協会の会館で、建築家谷口吉郎の設計。タイル貼白壁を迫出し、細い柱形に見せるコンクリート造で切妻造とし、全体にモダニズムをベースに和風建築の可能性を拓いた建物。階段廻りの亀甲石貼や折鶴形蛍光灯など金沢に相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014353"},{"id":"00003532","register_sub_id":"101","register_pk":"104522","name":"旧石川商銀信用組合小松支店","kana":"きゅういしかわしょうぎんしんようくみあいこまつしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県小松市京町19-5","lat":36.40815638,"lng":136.44866755,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積143㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"17 － 0084","desc":"加能合同銀行小松支店として建設と伝える。スクラッチタイル張，コーナーに円筒形の階段室塔屋を配した建築構成に特徴がある。ドリス式オーダーに半円アーチやイオニア式キャピタルなどを組合わせた玄関枠の意匠と内部階段室の螺旋状階段の造形に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003532"},{"id":"00013787","register_sub_id":"101","register_pk":"507749","name":"旧新保商店主屋","kana":"きゅうしんぼしょうてんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市安江町40-3","lat":36.57345,"lng":136.65544167,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"17 － 0302","desc":"店舗に北接して建つ。切妻造桟瓦葺の二階建町家で、正背面に下屋を付す。正面は出桁造で袖壁を設け、二階に格子窓を開いて一階南側に出格子を設ける。内部は一階は北を土間、南を一列二室、二階は床付座敷二室を配する。店舗と共に商店街の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013787"},{"id":"00013786","register_sub_id":"101","register_pk":"507748","name":"旧新保商店店舗","kana":"きゅうしんぼしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市安江町40-3","lat":36.5734,"lng":136.65544167,"geo_status":"db","era":"明治32年頃／明治後期・昭和前期・平成14年・令和2年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建及び土蔵造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建及び土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"17 － 0301","desc":"横安江町商店街の元履物店。街路に西面して建つ切妻造二階建町家。明治三二年大火後の再建で、焼け残った土蔵を取込んで一連の桟瓦葺大屋根を架け、正背面に下屋を付す。正面は出桁造で袖壁を設け、二階は格子窓を連ねる。明治大火後の商店街の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013786"},{"id":"00012143","register_sub_id":"101","register_pk":"352942","name":"旧高田桶店店舗兼主屋","kana":"きゅうたかだおけてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市扇町134","lat":36.560264,"lng":136.670806,"geo_status":"db","era":"明治後期／平成26年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、金属板葺、建築面積74㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"17-281","desc":"金沢城東方の旧天神町区域に建つ。木造二階建、切妻造平入。間口三間、奥行六間で附属屋を付す。通り土間沿いに店、茶の間、座敷を並べ、二階にアマと座敷を配す。軒高は極めて低く、もと板葺石置屋根の屋根勾配、正面柱の蔀戸痕跡など金沢の古い形式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012143"},{"id":"00000206","register_sub_id":"101","register_pk":"101196","name":"旧三田商店","kana":"きゅうみたしょうてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市尾張町1-8-5","lat":36.57070741,"lng":136.66295543,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積150㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"17 － 0004","desc":"交差点に面する部分を曲線で処理し、スクラッチタイルを貼る外観は質素であるが、正面の出入口に様式建築の装飾を集中させる点は特徴的である。施主の心意気を受けて施工されたこの建物は、金沢に残る数少ない昭和初期の名物建築として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000206"},{"id":"00003959","register_sub_id":"101","register_pk":"104949","name":"旧村松商店（村松商事ビル）","kana":"きゅうむらまつしょうてん（むらまつしょうじびる）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市尾張町1-111","lat":36.57057314,"lng":136.66290679,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積213㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0089","desc":"老舗糸卸小売商の自社ビル。南，西２方を道路に面する角地に建つ鉄筋コンクリート造の２階建で，南西隅部に塔屋を設ける。パラペット頂部や壁面に釉薬タイルの帯を付け，隅部は太い蛇腹を上下に並べたような壁仕上げとしアールデコ調の特徴ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003959"},{"id":"00011488","register_sub_id":"101","register_pk":"210453","name":"旧渡辺材木店店舗兼主屋","kana":"きゅうわたなべざいもくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市東山二丁目17","lat":36.57483389,"lng":136.66679111,"geo_status":"db","era":"明治30年頃／大正8年移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造二階建、瓦葺、建築面積135㎡","structure_material":"木造二階建","registered":"2017.05.02(平成29.05.02)","register_no":"17-0268","desc":"木造二階建、切妻造、桟瓦葺の間口五間で、明治三〇年頃に、材木商を開業するため建築された。大正期には道路拡張のため後方に曳家され、正面に平格子を取り付ける等の改修もなされた。良材を多用し、明治から大正にかけての金沢の町家の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011488"},{"id":"00003964","register_sub_id":"101","register_pk":"104954","name":"経田屋米穀店","kana":"きょうでんやべいこくてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市東山1-17-7","lat":36.57209538,"lng":136.66626888,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積134㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0094","desc":"製粉業を兼ねた米穀商の店舗。２階建，切妻造，桟瓦葺で，１階正面に出桁で庇を付け，内部は西に通り土間，東に表から店，茶の間を配し，現在２階にも居室をとる。１階の大戸，蔀戸，２階の格子窓，袖卯建による表構えは，町並みの景観形成に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003964"},{"id":"00004135","register_sub_id":"101","register_pk":"105125","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市十一屋町323","lat":36.5443628,"lng":136.66028945,"geo_status":"db","era":"昭和12／昭和27頃曳家改造","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0107","desc":"当初料亭として建てられ，第２次大戦後曳家の上住宅に改造されたもの。１・２階にそれぞれ設けられる床棚付の書院に，白鳥をあしらった欄間彫刻など質の高い意匠を備える。全体にたちが高く，２階部に縁と小庇を廻すなど近代和風建築の好例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004135"},{"id":"00004132","register_sub_id":"101","register_pk":"105122","name":"澁江家住宅主屋","kana":"しぶえけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市東山1-4-1","lat":36.57282379,"lng":136.66576489,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積62㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0104","desc":"平入の町屋で，西側で街路に面する。２階の大屋根は出桁造とし，腕木を二重に重ねて意匠を凝らす。１階は南寄りに玄関を置き，茶の間など居室を設ける。２階は東に縁を設ける座敷を中心に，前室２室と納戸を配している。金沢における大正期の町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004132"},{"id":"00001069","register_sub_id":"101","register_pk":"102059","name":"白銀屋旅館茶室","kana":"しろがねやりょかんちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市山代温泉万松通７","lat":36.28892549,"lng":136.36069875,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建，瓦葺，建築面積49㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0034","desc":"山代温泉では建築年代が古い旅館の付属施設で，敷地の北西隅に建つ。外観は簡素で一部に改造もみられるが，内部は木部全体を漆塗りで仕上げ，天井を折り上げるなど書院風のつくりになり，建築当初の雰囲気をよくとどめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001069"},{"id":"00001068","register_sub_id":"101","register_pk":"102058","name":"白銀屋旅館本館","kana":"しろがねやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県加賀市山代温泉万松通７","lat":36.28879019,"lng":136.36094001,"geo_status":"db","era":"文政年間","year":1824,"year_source":"estimated","year_min":1818,"year_max":1830,"year_label":"文政年間","structure":"木造２階建，瓦葺，建築面積520㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0033","desc":"山代温泉で江戸時代から続く老舗の旅館。本館は，間口の広い町家で，吹き抜けに架構をみせた「わくのうち」と呼ばれる構法を用いた部屋を持つ，この地方特有の形式になる。正面にべんがら格子を入れ，両袖にうだつを建てた外観にも特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001068"},{"id":"00004353","register_sub_id":"101","register_pk":"105343","name":"高澤ろうそく店主屋","kana":"たかざわろうそくてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市一本杉町11-1","lat":37.04640711,"lng":136.9640096,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0119","desc":"七尾の中心を東西に貫く通りに北面して建つ。桁行５間半梁間４間半，土蔵造２階建，切妻造，桟瓦葺で，内部は１階を店舗，２階に展示スペース，座敷を配す。２階は小窓以外は塗り込め，１階の両端部も壁とする閉鎖的なつくりで，重厚な町家の正面を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004353"},{"id":"00004355","register_sub_id":"101","register_pk":"105345","name":"夛田家住宅（旧上野啓文堂）主屋","kana":"ただけじゅうたく（きゅううえのけいぶんどう）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県七尾市一本杉町32-1","lat":37.0470962,"lng":136.96275522,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0121","desc":"万年筆専門文具店として建設。木造２階建で，内部は和室だが，通りに面した正面はモルタル塗壁を高く立ち上げた看板建築。万年筆とインク瓶のモチーフや柱頭飾り風の特徴ある装飾を付け，２階窓をペン先型に象るなど，斬新な意匠で町並景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004355"},{"id":"00004134","register_sub_id":"101","register_pk":"105124","name":"谷庄古美術店主屋","kana":"たにしょうこびじゅつてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市十間町44","lat":36.57069532,"lng":136.65739632,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積214㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0106","desc":"和洋並立の店舗兼住宅。正面中央に玄関を開き，洋館の１階を店舗とし，和館部は１間幅の畳廊下を通して座敷，仏間，茶室等を配する。和館立面は洋館に揃えて高くし，洋館正面は３連のアーチ窓の２階と大窓の１階を対比させ，特徴的な外観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004134"},{"id":"00004357","register_sub_id":"101","register_pk":"105347","name":"戸市酒販酒蔵","kana":"といちしゅはんさかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県小松市大川町2-45","lat":36.41473228,"lng":136.45046217,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積75㎡","structure_material":"木骨石造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0123","desc":"小松大橋南橋詰すぐ近くに建つ。２階建，切妻造，妻入で，木造軸組の外側に板状の切石を積み上げて漆喰で仕上げ，屋根野地板の上にも切石を張り桟瓦を葺く。西面１階戸口及び２階の小窓以外に開口を設けない閉鎖的なつくりで，防火的な外観を表通りに見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004357"},{"id":"00006449","register_sub_id":"101","register_pk":"107432","name":"戸水屋菓子店店舗兼主屋","kana":"とみずやかしてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市寺町二丁目45他","lat":36.55004741,"lng":136.65558679,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積172㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"17 － 0164","desc":"寺町大通りに東面して建つ。正面桁行５間、梁間７間、切妻造、桟瓦葺、平入のたちの高い２階建町家で、北寄りに土間を通し、南３間分を店とする。正面は出桁造とし、１階の欄間下に木製庇を差し掛け、２階には袖卯建を付けるなど存在感ある表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006449"},{"id":"00004354","register_sub_id":"101","register_pk":"105344","name":"鳥居醤油店主屋","kana":"とりいしょうゆてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市一本杉町29","lat":37.0469638,"lng":136.96299549,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積124㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0120","desc":"七尾の中心を東西に貫く通りに北面して建つ。桁行７間半梁間４間半，土蔵造２階建，切妻造，桟瓦葺で，内部は１階を店や座敷，２階は主に物置とする。間口が広く，軒の出の小さい重厚な構えで，つし２階としたたちの低い外観は，町並の景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004354"},{"id":"00003419","register_sub_id":"101","register_pk":"104409","name":"西検番事務所","kana":"にしけんばんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市野町2-25-17","lat":36.556477,"lng":136.64743,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積501㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0081","desc":"犀川大橋南方に位置し，芸妓衆の稽古場兼管理事務所として建設。洋風の事務所棟と中庭を隔てた木造２階建，和風の稽古場棟とから成り，事務所棟は寄棟造，桟瓦葺の木造２階建，下見板張で，明治期に流行したバージボード付きの玄関ポーチに特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003419"},{"id":"00005131","register_sub_id":"101","register_pk":"106121","name":"橋本酒造旧精米所","kana":"はしもとしゅぞうきゅうせいまいしょ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32757593,"lng":136.3858831,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積99㎡","structure_material":"土蔵造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0142","desc":"釜場及び白米庫の西方，敷地南辺沿いに東西棟で建つ。桁行６間，梁間５間，切妻造，桟瓦葺の土蔵造平屋建で，北面東寄りと東面北寄りに出入口を設ける。南側梁行２間の土蔵と北側梁行３間トラス小屋の土蔵を接合し，一体的な屋根を架けた特異なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005131"},{"id":"00005122","register_sub_id":"101","register_pk":"106112","name":"橋本酒造主屋","kana":"はしもとしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32772886,"lng":136.38654531,"geo_status":"db","era":"文化11","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造2階建、瓦葺、建築面積391㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0133","desc":"街道に東面して建つ。主体部は桁行７間，梁間７間規模，切妻造，桟瓦葺のつし２階建町家で，南寄りに通り土間を通し，南に１列，北に３列の諸室を配する。南端はもと釜場で，高い吹き抜けで，棟上に越屋根を載せる。江戸後期における造り酒屋の主屋の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005122"},{"id":"00005129","register_sub_id":"101","register_pk":"106119","name":"橋本酒造冷蔵室","kana":"はしもとしゅぞうれいぞうしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.327923,"lng":136.386078,"geo_status":"db","era":"大正期／昭和31移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木骨石造2階建、瓦葺、建築面積93㎡","structure_material":"木骨石造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0140","desc":"貯蔵庫の北西，敷地北辺沿いに東西棟で建つ。桁行５間，梁間４間規模，切妻造，桟瓦葺，妻入の木骨石造２階建で，東面に２間の下屋を差し掛けて戸口を開く。屋根は置屋根である。内部は中央に１本の柱を建て，地棟に木太い合掌を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005129"},{"id":"00005120","register_sub_id":"101","register_pk":"106110","name":"春成酒造店主屋","kana":"はるなりしゅぞうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県七尾市今町15","lat":37.04419062,"lng":136.96927131,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積191㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0131","desc":"能登街道の起点となる「違い堀」の近くに位置する。桁行７間半，梁間６間，切妻造，桟瓦葺，平入の木造２階建で，通りに西面して建ち，北方を店舗，事務室とし，南方に８畳を３室並べる。たちの高いせがい造の町家で，規模も大きく，周囲で際だった存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005120"},{"id":"00004131","register_sub_id":"101","register_pk":"105121","name":"平木屋旗店","kana":"ひらきやはたてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市菊川1-12-1","lat":36.55054674,"lng":136.6629594,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積110㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0103","desc":"金沢の中心地，犀川右岸に建つ平屋建，平入の町家。建物は東寄りに土間を通し，西寄りに表側からミセ，茶の間，床と仏間を備える奥の間を配する。現在は鉄板葺であるが，かつては板葺であった。城下町金沢の近世の商家の様子を今日に伝える建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004131"},{"id":"00011286","register_sub_id":"101","register_pk":"209122","name":"法師延命閣","kana":"ほうしえんめいかく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県小松市粟津町カ17他","lat":36.331897,"lng":136.44772,"geo_status":"db","era":"明治44頃","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積247㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0263","desc":"粟津温泉の老舗旅館。延命閣は敷地の中央に独立して建つ宿泊棟で、浴室を併設する。大床と書院を備えた一二畳半大の上段を中心に、矩折の畳廊下を廻らし、さらに座敷を連ねて土縁を設ける独特の平面構成とする。色壁を用いて加賀らしい華やかな内部空間を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011286"},{"id":"00011287","register_sub_id":"101","register_pk":"209123","name":"法師玄関棟","kana":"ほうしげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県小松市粟津町ワ46-1","lat":36.331348,"lng":136.44735,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積334㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0264","desc":"粟津温泉の中心地に位置する老舗旅館。玄関棟は前面に玄関と帳場、背面にもと客室を並べる平面で、内部には高い吹き抜け空間を備え、梁組等を見せる。外観では正面側二階に円窓を横に四つ並べた出窓を張り出す特異な形態を見せ、法師の象徴として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011287"},{"id":"00001071","register_sub_id":"101","register_pk":"102061","name":"山岡商山堂（山岡ビル）","kana":"やまおかしょうざんどう（やまおかびる）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県加賀市山中温泉湯の出町レ26-3","lat":36.24621076,"lng":136.37282133,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積108㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0036","desc":"山中温泉の中心街にある。もと漆器店の本店で現在はギャラリー等に利用されている。昭和６年の大火後に建てられたもので，地域で最初期の鉄筋コンクリート造の建物として貴重。交差点に面したつくられた入口廻りの装飾等にも時代の特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001071"},{"id":"00006633","register_sub_id":"101","register_pk":"107616","name":"あめや呉服店店舗兼主屋","kana":"あやめごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県鯖江市本町3-206","lat":35.946758,"lng":136.18524465,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0060","desc":"鯖江市街地の旧北陸道に東面して建つ。桁行５間半で、南面は入母屋造、北面は隣家に接する２階建平入町家。２階は黒漆喰塗で塗り込め、正面に２ヶ所、南側に３ヶ所の窓を開ける。１階正面にミセ、奥に座敷を設ける。鉄製扉で大壁造とする重厚な外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006633"},{"id":"00006634","register_sub_id":"101","register_pk":"107617","name":"あめや呉服店西蔵","kana":"あやめごふくてんにしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県鯖江市本町3-206","lat":35.94674439,"lng":136.18508812,"geo_status":"db","era":"昭和初期／昭和前期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0062","desc":"東蔵の西奥に棟を並行に建つ。桁行４間梁間２間半規模の土蔵造２階建で、切妻造桟瓦葺。１階内部に４畳半の茶室を置く。基礎は笏谷石を用い、外壁はもとは漆喰仕上げであったが、モルタル仕上げに改修された。隣接して土蔵が建ち並び、存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006634"},{"id":"00006635","register_sub_id":"101","register_pk":"107618","name":"あめや呉服店東蔵","kana":"あやめごふくてんひがしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県鯖江市本町3-206","lat":35.94674962,"lng":136.1850067,"geo_status":"db","era":"大正2／昭和前期改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0061","desc":"主屋の西奥、中庭を介して建つ。南北棟の切妻造桟瓦葺、桁行４間半梁間３間の土蔵造２階建である。目地を切るモルタル塗仕上げとし、上方を白漆喰で塗り込める。２階南窓は庇を設け、分銅形の紋様をもつ掛子塗戸片開をたてる。質実な意匠の土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006635"},{"id":"00000430","register_sub_id":"101","register_pk":"101420","name":"恵美写真館表門","kana":"えみしゃしんかんおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市本町3-1-28","lat":35.94661377,"lng":136.18627878,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造薬医門，銅板葺","structure_material":"木造薬医門","registered":"1998.01.16(平成10.01.16)","register_no":"18 － 0006","desc":"主屋の正面東方にあり，道路に面して建つ。伝統的な薬医門の形式をもつが，アーチ形の屋根，正面の虹梁等に洋風の意匠を取り入れた特異な形態の門。和風を基調にして要所に洋風を取り入れた意匠は，本館と共通する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000430"},{"id":"00000429","register_sub_id":"101","register_pk":"101419","name":"恵美写真館洋館","kana":"えみしゃしんかんようかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市本町3-1-28","lat":35.94668857,"lng":136.18617864,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建，瓦葺，建築面積42㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"18 － 0005","desc":"寄棟造，２階建の主体部に入母屋造の玄関ポーチを正面に付けた建物。全体的には和風になるが，玄関ポーチの開口部や軒廻りの装飾等に洋風の意匠を取り入れている。外壁は左官仕上で，各部の装飾等に優れた技能が発揮されている。左官は石動芳次郎がつとめた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000429"},{"id":"00016368","register_sub_id":"101","register_pk":"536435","name":"加藤善次郎商店店舗兼主屋","kana":"かとうぜんじろうしょうてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市本町241-2","lat":35.89833056,"lng":136.16600833,"geo_status":"db","era":"明治前期／昭和前期・同30年代・同54年・同61年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積132㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"18 - 0271","desc":"旧北陸道沿いに東面して建つ、打刃物問屋の店舗兼主屋。二階建切妻造平入桟瓦葺で正面に下屋を付し、二階は両端に袖壁を設け、軒は出桁造とする。一階内部は北東隅を土間とし、南側に一列３室を配す。一階上屋筋に摺上戸を留めるなど、古風な構えを残す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016368"},{"id":"00016369","register_sub_id":"101","register_pk":"536436","name":"加藤善次郎商店土蔵","kana":"かとうぜんじろうしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市本町241-2","lat":35.89833611,"lng":136.16581389,"geo_status":"db","era":"昭和7年／昭和前期増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"18 - 0272","desc":"店舗兼主屋の西に位置する家財蔵。２階建切妻造妻入桟瓦葺で、外壁は漆喰塗で、一階はモルタル洗出仕上に目地を切り石貼風とする。東面の下屋内には床構え付きの座敷を配す。戸口や窓に鉄扉を付すなど厳重なつくりで、西妻に屋号を掲げて地域の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016369"},{"id":"00013534","register_sub_id":"101","register_pk":"504901","name":"旧浅井薬店（小澤金物店）店舗兼主屋","kana":"きゅうあさいくすりてん（おざわかなものてん）てんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市幸町222-1","lat":35.90337222,"lng":136.16645556,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"18 － 0215","desc":"武生城下の中心部に位置。二階建切妻造桟瓦葺。正面の出入口脇にショーウィンドウを構える。内部は土間脇に旧調剤室があり板間のミセを張り出す。奥の通り土間沿いに八畳、奥に浴室便所などを突出する。表構えに当時の流行を取り入れた商店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013534"},{"id":"00009751","register_sub_id":"101","register_pk":"195580","name":"旧大井百貨店（大井洋装店）","kana":"きゅうおおいひゃっかてん（おおいようそうてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市元町81他","lat":35.90147502,"lng":136.16553409,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建地階付、建築面積239㎡","structure_material":"鉄筋コンクリート造3階建地階付","registered":"2013.12.24(平成25.12.24)","register_no":"18 － 0118","desc":"武生中心部の角地に建つ。間口八・七メートル奥行二八メートル、鉄筋コンクリート造三階建で地階をつける。正面入口上部に装飾的な半円アーチを設け、街路に面する北及び西面に大オーダーを廻らし、柱間に三連窓を配する。当地の賑わいを物語る近代商業建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009751"},{"id":"00013535","register_sub_id":"101","register_pk":"504902","name":"旧大木道具店店舗兼主屋","kana":"きゅうおおきどうぐてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市三国町北本町四丁目423-6","lat":36.21367778,"lng":136.14912778,"geo_status":"db","era":"昭和前期／平成30年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"18 － 0216","desc":"九頭竜川河口の町中にある商店。街路の角地に建つ木造二階建、入母屋造桟瓦葺で、建物東半三方に下屋を廻してショーウインドウを設け、二階には上げ下げ窓を並べる。内部二階座敷などは往時の姿を良く残す。建ちの高い外観が、町並のアクセントとなる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013535"},{"id":"00013536","register_sub_id":"101","register_pk":"504903","name":"旧大木道具店土蔵","kana":"きゅうおおきどうぐてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市三国町北本町四丁目423-6","lat":36.21354722,"lng":136.148925,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積75㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"18 － 0217","desc":"敷地西端に東面して建つ。二階建の土蔵造桟瓦葺で北面に大振りの下屋を設ける。外壁は腰高くモルタル塗に目地を切り、上部は漆喰を軒先まで塗込める。一階は東西二室に区切って東室を床を備えた座敷とし、二階を物置とする。街路景観の一角を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013536"},{"id":"00013716","register_sub_id":"101","register_pk":"505249","name":"旧大和田銀行本店社屋","kana":"きゅうおおわだぎんこうほんてんしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県敦賀市相生町8-13他","lat":35.65681111,"lng":136.06866111,"geo_status":"db","era":"明治34年／明治37年・平成8年改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 218","desc":"敦賀の中心部に位置。木造二階建切妻造桟瓦葺平入。正面にパラペットを立上げて陸屋根にみせ、矩形の縦長窓を並べて洋風意匠の外観とする。正面を客溜り、営業室として両脇に応接室を配し、背後に和室を並べる。地方銀行の本店遺構として通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013716"},{"id":"00007988","register_sub_id":"101","register_pk":"128820","name":"旧京都電燈株式会社高浜営業店","kana":"きゅうきょうとでんとうかぶしきがいしゃたかはまえいぎょうてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県大飯郡高浜町宮崎73字島崎5-2","lat":35.49008632,"lng":135.54857673,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"18-0082","desc":"道路沿いに東面して建つ。木造２階建、寄棟造桟瓦葺。桁行梁間とも８．９ｍの平面になる。正面は２階にバルコニーを造り、中央に玄関を設け、半円アーチ窓を開ける。ベージュ色のモルタル仕上げで多彩な装飾を施す。左右対称を強調した正面構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007988"},{"id":"00009937","register_sub_id":"101","register_pk":"196084","name":"旧敦賀倉庫株式会社新港第一号・第二号・第三号倉庫","kana":"きゅうつるがそうこかぶしきがいしゃしんこうだいいちごう・だいにごう・だいさんごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県敦賀市蓬萊町1-4","lat":35.65948445,"lng":136.06978071,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積994㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"18 － 0121","desc":"敦賀港の中央に建つ。鉄筋コンクリート造平屋建の倉庫で、段差付のパラペットや小窓の上下の小庇、出入口の庇で水平線を強調する。隅部は一段高い塔屋状としてタイルを逆Ｌ字形に貼りアクセントとする。当時流行の国際様式の影響が看取される大型倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009937"},{"id":"00008682","register_sub_id":"101","register_pk":"149403","name":"旧旅籠若狭屋","kana":"きゅうはたごわかさや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県南条郡南越前町今庄75字東中町13","lat":35.77317227,"lng":136.19671079,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積160㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0103","desc":"旧今庄宿に所在し、旧北国街道に西面する。間口10ｍ奥行9.5ｍの平入町家。木造2階建、切妻造鉄板葺とし、前後に庇を付ける。正面は中央間を出入口とし、その他は平格子を構える。2階に客間、1階に和室や台所などを配する。宿場町の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008682"},{"id":"00011126","register_sub_id":"101","register_pk":"205233","name":"旧増尾家住宅主屋","kana":"きゅうますおけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県南条郡南越前町板取35-1","lat":35.726969,"lng":136.154029,"geo_status":"db","era":"文政6","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造2階建、茅葺、建築面積111㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"18 - 0157","desc":"北国街道の板取宿に建つもと旅籠。茅葺屋根を兜造妻入とする。正面側にニワを設け、床上部は二列とし、表列をクチノマ、ナカノマ、オクノマの三室、奥列をダイドコとブツマに分ける。北国街道に面した旅籠屋の意匠と間取りを伝える民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011126"},{"id":"00000406","register_sub_id":"101","register_pk":"101396","name":"旧森田銀行本店","kana":"きゅうもりたぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県坂井市三国町南本町3-217-2","lat":36.21234617,"lng":136.15033043,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積163㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"18 － 0004","desc":"鉄筋コンクリート造，２階建で，外壁に茶系タイルと擬石を張り，内外とも古典主義的な意匠でまとめる。内部は，１階が吹き抜けの営業室と個室，２階部分背後に会議室を置く。県内では初期の本格的な鉄筋コンクリート造建築で，質も高い。設計は，山田七五郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000406"},{"id":"00008671","register_sub_id":"101","register_pk":"149392","name":"旧料亭花月楼","kana":"きゅうりょうていかげつろう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県勝山市106字西中下後町28","lat":36.06048354,"lng":136.49736692,"geo_status":"db","era":"明治37年／大正4年増築","year":1904,"year_source":"converted","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積341㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0092","desc":"勝山市中心部の本町に所在する。木造2階建、入母屋造桟瓦葺の2棟を棟をずらして接続し、南側の棟が後年の増築になる。1階に5室、2階に10室の座敷を配する。北棟の2階奥を32畳の大広間とし、幅2間半のトコや傘状に棹縁を配る天井など意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008671"},{"id":"00008449","register_sub_id":"101","register_pk":"134845","name":"酒井家住宅主屋","kana":"さかいけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市下深江町116他","lat":35.94813186,"lng":136.18534557,"geo_status":"db","era":"明治43年／昭和57年頃改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積153㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0084","desc":"旧北国街道に東面する町家。正面八・五メートル奥行一二メートルの木造二階建、切妻造桟瓦葺、正・背面に庇、側面に下屋を付設する。一階に事務室や座敷、仏間、二階に茶室ほかを配する。一階に出格子を構え二階を塗り込めるなど、町家らしい構えを示す","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008449"},{"id":"00008450","register_sub_id":"101","register_pk":"134846","name":"酒井家住宅土蔵","kana":"さかいけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市下深江町116他","lat":35.94811763,"lng":136.18525098,"geo_status":"db","era":"明治中期／昭和57年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0085","desc":"主屋後方、中庭を介して建つ。桁行七・六メートル梁間五・七メートル、切妻造桟瓦葺の二階建土蔵。基礎を笏谷石とし、外壁をモルタル洗い出し仕上げ、腰を海鼠壁とする。窓や出入口まわりに漆喰仕上げを残し、庇には丁寧な仕上げの鏝細工が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008450"},{"id":"00000129","register_sub_id":"101","register_pk":"101119","name":"白鳥会館","kana":"しらとりかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県小浜市小浜白鳥25","lat":35.49282182,"lng":135.73755222,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建，瓦葺，建築面積59㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"18 － 0002","desc":"明治２１年の大火後に，土蔵造で建築されたもので，元薬品製造販売に使われた店蔵である。正面の開口部廻りや腰壁等壁面の一部等に煉瓦を用いている。特に正面外観の花弁型の特殊煉瓦を使用して特異なアーチを形造る意匠は類例が少なく見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000129"},{"id":"00000130","register_sub_id":"101","register_pk":"101120","name":"白鳥会館煉瓦塀","kana":"しらとりかいかんれんがべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市小浜白鳥25","lat":35.49275709,"lng":135.73751914,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"煉瓦造，延長4.0m","structure_material":"煉瓦造","registered":"1997.05.07(平成9.05.07)","register_no":"18 － 0003","desc":"店蔵と一体的に造られた煉瓦塀で，小規模ながら煉瓦積みの技術に見るべきものがある。店蔵の棟札に煉瓦工の名が記されており，手がけた職人の名が知られる。当時この地方で煉瓦工が職能として成立していたことを示すものとして，技術史上も意義が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000130"},{"id":"00014479","register_sub_id":"101","register_pk":"513893","name":"杉原商店事務所","kana":"すぎはらしょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市不老町17字東町2-1他","lat":35.9072,"lng":136.24454167,"geo_status":"db","era":"昭和8年／同50年頃移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0238","desc":"主屋の北東に南面する和紙問屋の事務所。土蔵造2階建、切妻造平入桟瓦葺で南に下屋を付す。外壁は漆喰仕上で二階腰まで簓子下見板を張り、北に平格子付窓を４箇所開く。内部１階の南は廊下で西端に踏込土間、北は事務所とする。敷地北東の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014479"},{"id":"00009753","register_sub_id":"101","register_pk":"195582","name":"寿屋対碧亭","kana":"すやたいへきてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市粟田部町29字船佐山41","lat":35.91706284,"lng":136.24090872,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺及び銅板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"18 － 0120","desc":"料理旅館の庭園内に建ち、木造平屋建、入母屋造茅葺で、南西隅に桟瓦葺の四畳半を張出す。主体部はトコ付の六畳の西側に四畳前室を、東側に山形窓のトコをもつ二畳を配し、周囲に下屋を廻らせる。四畳半には円窓など多彩な窓を穿つ、開放的な構成の草庵風茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009753"},{"id":"00003422","register_sub_id":"101","register_pk":"104412","name":"南越（旧中村商店）","kana":"なんえつ（きゅうなかむらしょうてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市蓬莱町125","lat":35.90224738,"lng":136.16837452,"geo_status":"db","era":"明治45／昭和5頃・昭和15増改造","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造3階建、瓦葺、建築面積89㎡","structure_material":"木造3階建","registered":"2003.07.01(平成15.07.01)","register_no":"18 － 0022","desc":"木造３階建，切妻造，桟瓦葺。当初は２階建で，２度の増改造を経ている。間口は４間で，１・２階を店舗及び倉庫とし，３階には和室４室を設ける。正面外観は２階・３階に大きな窓４カ所を設け，和風を基調としながら近代的な様相をも併せ持つ商店建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003422"},{"id":"00006492","register_sub_id":"101","register_pk":"107475","name":"都菓子舗作業所","kana":"みやこかしほさぎょうじょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県小浜市小浜鹿島41","lat":35.493023,"lng":135.73872876,"geo_status":"db","era":"明治中期／大正期曳家","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0054","desc":"明治２１年の大火後に再建されたもとの主屋で、敷地北方に曳家され洋菓子製造の作業場となる。桁行３間半、梁間３間半、切妻造、桟瓦葺、平入の２階建町家で、２階は６畳と４畳半、板間２室とする。１階は改造されてはいるが、明治中期の町家の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006492"},{"id":"00006451","register_sub_id":"101","register_pk":"107434","name":"都菓子舗店舗兼主屋","kana":"みやこかしほてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県小浜市小浜鹿島41","lat":35.492985,"lng":135.73877,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0053","desc":"中町通りに南面して建つ。桁行３間半、梁行５間半、切妻造、桟瓦葺、平入の２階建洋風町家で、東側に通り土間、西端に半間幅の通路を通し、店の奧にトコ付の６畳間を配する。たちが高く、２階をドイツ下見板張とし、庇の幕板を看板とした正面は周囲で際立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006451"},{"id":"00008672","register_sub_id":"101","register_pk":"149393","name":"料亭板甚蔵座敷","kana":"りょうていいたじんくらざしき","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県勝山市95字西上袋田町東中下後町27他","lat":36.05981438,"lng":136.49890726,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"converted","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階地下1階建、瓦葺、建築面積64㎡","structure_material":"土蔵造2階地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0093","desc":"勝山市中心部を貫く本町通りに店を構える料亭の西奥に位置する。桁行11ｍ梁間5.7ｍ、土蔵造2階建、切妻造桟瓦葺。各階に2室の座敷を配し、コンクリート基礎に地下室を造る。1階奥の主座敷は、トコを黒漆喰塗に竹の落掛とするなど独特の意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008672"},{"id":"00006452","register_sub_id":"101","register_pk":"107435","name":"料亭開花亭","kana":"りょうていかいかてい","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県福井市中央3-1209他","lat":36.062721,"lng":136.213394,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階建、瓦葺、建築面積355㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0056","desc":"足羽川の北、河畔に建つ料亭。通りの南に占める敷地のやや奥に東西棟で主部を設け、その東端に南北棟を付ける。１階は川に面して客間４室を設け、２階は７２畳の大広間や客間を配する。丁寧な造りの座敷飾りや天井、繊細な明障子など、伝統的な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006452"},{"id":"00010774","register_sub_id":"101","register_pk":"201609","name":"料亭天狗楼表門","kana":"りょうていてんぐろうおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県鯖江市中小路町32-4","lat":35.945497,"lng":136.186179,"geo_status":"db","era":"昭和26頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0142","desc":"料亭棟の東に接道して建つ。間口一・九メートルの棟門で、切妻造桟瓦葺とし、棟石及び鬼は笏谷石で作る。冠木上に繊細な筬欄間を嵌めるなど瀟洒な意匠を見せる。料亭棟の玄関とやや軸線をずらし、料亭の導入部に変化を与えると共に、通りの景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010774"},{"id":"00010772","register_sub_id":"101","register_pk":"201607","name":"料亭天狗楼調理棟","kana":"りょうていてんぐろうちょうりとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市中小路町32-4","lat":35.945614,"lng":136.186156,"geo_status":"db","era":"昭和元","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0140","desc":"料亭棟の北に接続し、東の道路に面して建つ二階建の建物。一階は南端に通り土間を設け、厨房としての機能を当初から担っている。正面外観は黒漆喰で塗込め、一階に出格子、二階を出桁で支えて両脇に袖壁を設けるなど、当地の伝統的な町家の形式となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010772"},{"id":"00010773","register_sub_id":"101","register_pk":"201608","name":"料亭天狗楼土蔵","kana":"りょうていてんぐろうどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市中小路町32-4","lat":35.945642,"lng":136.185945,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0141","desc":"敷地北西に建つ二階建の土蔵。南北棟で東に庇を大きく張出して蔵前とし、西面にも小庇のついた出入口を設ける。小屋は登梁形式とし、内部に幅広の床板を張る。蔵前部分の腰は洗出し仕上げで石積風に目地を切る。料亭に附属する昭和初期の土蔵として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010773"},{"id":"00010771","register_sub_id":"101","register_pk":"201606","name":"料亭天狗楼料亭棟","kana":"りょうていてんぐろうりょうていとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市中小路町32-4","lat":35.945562,"lng":136.186039,"geo_status":"db","era":"明治中期／昭和初期移築・同41改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積198㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0139","desc":"もと陣屋町の中に建つ二階建の料亭。料亭棟は東を通る道路からやや引いて建て、敷地南西隅の庭に面して座敷を並べる。一階に前室付の座敷、二階に大広間を配す。赤色壁や扇形の下地窓等に料亭らしい華やぎを見せ、また玄関の笏谷石敷などに地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010771"},{"id":"00007482","register_sub_id":"101","register_pk":"108464","name":"若栗商店店舗兼主屋","kana":"わかぐりしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市吉江町1字一ノ割1他","lat":35.985413,"lng":136.169968,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積237㎡","structure_material":"木造2階一部平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0074","desc":"七曲りと称される通りに西面する。切妻造妻入桟瓦葺で、正側面に下屋をまわし、南面前方と背面に角屋を付ける。内部は正面に土間床のミセを設け、その奥を２列各３室の居室とする。ブツマやキュウソクマ、ザシキなどが、漆塗や欄間彫刻で華やかに飾られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007482"},{"id":"00000239","register_sub_id":"101","register_pk":"101229","name":"飯島家住宅（旧飯島楼）","kana":"いいじまけじゅうたく（きゅういいじまろう）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県山梨市小原西765","lat":35.69478583,"lng":138.69016524,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建，瓦葺，建築面積122㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"19 － 0013","desc":"旧青梅街道の小原宿の中ほどに街道に面して建つ。木造２階建で、ほぼ長方形の平面に入母屋造妻入の玄関を付し、１階平面には中廊下に六畳の客間を配する。２階の縁から富士山を望むことができたといい、近代初期の旧街道の面影を今に伝えて親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000239"},{"id":"00010965","register_sub_id":"101","register_pk":"208935","name":"いさご屋旅館","kana":"いさごやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3696","lat":35.377818,"lng":138.425123,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造3階建、瓦葺、建築面積201㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"19-0076","desc":"久遠寺の参道沿いにある旅館。木造三階建、入母屋造平入。入母屋の玄関を設け、二、三階の各窓には刎高欄の手摺を設ける。二階南側は大広間とし、三階は客室を並べる。ヒノキ一枚板の階段踏板や寄木、網代天井など趣向を凝らす。古刹の門前に風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010965"},{"id":"00010964","register_sub_id":"101","register_pk":"208934","name":"岩下温泉旅館旧館","kana":"いわしたおんせんりょかんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県山梨市上岩下1055","lat":35.683648,"lng":138.654182,"geo_status":"db","era":"明治8頃／昭和17頃増築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階一部地下1階建、瓦葺、建築面積159㎡","structure_material":"木造2階一部地下1階建","registered":"2016.02.25(平成28.02.25)","register_no":"19-0075","desc":"奥に東西棟の温泉棟、これと直交した前方に玄関棟があり、ほぼ南面して建つ。明治八年頃の温泉棟は二階建で、一部地階に源泉浴場がある。増築の玄関棟も二階建で、二階に瀟洒な座敷を設ける。伝統的な和風建築で、温泉地の歴史的景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010964"},{"id":"00001110","register_sub_id":"101","register_pk":"102100","name":"小原屋原田商店油蔵","kana":"おばらやはらだしょうてんあぶらぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.5482812,"lng":138.45920976,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積152㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0036","desc":"敷地奥に東面して建つ大規模な２階建の土蔵で、前面に幅１間の土庇が付く。内部は間仕切り壁で３室に区画され、南端部の部屋は２階建とするが他は吹き抜けである。開口部の少ない閉鎖的な土蔵であるが、正面腰壁をなまこ壁とするなど丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001110"},{"id":"00001109","register_sub_id":"101","register_pk":"102099","name":"小原屋原田商店塩蔵","kana":"おばらやはらだしょうてんしおぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.54832178,"lng":138.45936395,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積86㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0035","desc":"文庫蔵の西に建つ２階建の土蔵で、正面に土庇が付く。１階は仕切壁で２室に区画され、西側の部屋を塩蔵として使用したためその名がある。東側の部屋は２階へ通じる階段があり、物置として使われた。正背面にのみ開口部を開くが、全体に簡素な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001109"},{"id":"00001111","register_sub_id":"101","register_pk":"102101","name":"小原屋原田商店新座敷","kana":"おばらやはらだしょうてんしんざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.54828283,"lng":138.45935746,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積31㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0037","desc":"文庫蔵に直交して建つ平屋建の建物。小規模であるが、外観は周囲にあわせて土蔵造としている。全体として簡素な外観になるが、内部は近年土間床に改造し従業員の食堂として使用している。商家の屋敷構を構成する要素として貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001111"},{"id":"00001108","register_sub_id":"101","register_pk":"102098","name":"小原屋原田商店文庫蔵","kana":"おばらやはらだしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.54830068,"lng":138.4594873,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積53㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0034","desc":"敷地の北側角地に建つ切妻造、２階建の小規模な土蔵。内部は１，２階とも１室とする。１階正面に扉口及び小窓があるほか、２階も両妻に小窓を開くのみの閉鎖的な構成になる。軒廻りは疎垂木を見せるが、外壁とも塗込の漆喰仕上げとする標準的な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001108"},{"id":"00001107","register_sub_id":"101","register_pk":"102097","name":"小原屋原田商店店蔵","kana":"おばらやはらだしょうてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.5482033,"lng":138.45947594,"geo_status":"db","era":"安政3頃","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積78㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0033","desc":"富士川の舟運で栄えた鰍沢で、弘化３年の創業と伝える商家。往時は主に塩などの仲買を行った。店蔵は１階前面を店舗とし、２階は居室に充て前面に細格子窓を開く伝統的な構えになる。もと表通りに面していたが、道路拡幅のため昭和３５年に曳き屋された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001107"},{"id":"00004753","register_sub_id":"101","register_pk":"105743","name":"風間酒造酒店","kana":"かざましゅぞうさけてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山下於曽910","lat":35.69735618,"lng":138.72730142,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"19 － 0051","desc":"主屋の北東，表通り際に建つ。桁行５間半，梁間３間，土蔵造，２階建，寄棟造，桟瓦葺で，１階を店舗とし東面戸口部分は土庇とする。２階の軒を腕木で大きく持ち出して塗込め，道側の窓を掛子塗とするなど重厚な造りで，主屋とともに独特の店構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004753"},{"id":"00014807","register_sub_id":"101","register_pk":"519065","name":"旧料亭角田主屋","kana":"きゅうかくだけおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県富士吉田市下吉田三丁目827-3他","lat":35.49287222,"lng":138.80203889,"geo_status":"db","era":"昭和3年／昭和中期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積240㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0178","desc":"下吉田の月江寺参道に西面する元料亭。主屋は二階建入母屋造平入桟瓦葺で、正面に唐破風造の玄関を付し、二階中央に軒唐破風に千鳥破風を重ね、腰組付高欄を廻らした華やかな外観。二階座敷は出節床柱、折上格天井など昭和初期の豪壮な気風を示す料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014807"},{"id":"00014808","register_sub_id":"101","register_pk":"519066","name":"旧料亭角田脇門","kana":"きゅうかくだけわきもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県富士吉田市下吉田三丁目827-3","lat":35.49276667,"lng":138.80208611,"geo_status":"db","era":"昭和3年頃／昭和30年代移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、鉄板葺、間口1.8m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0179","desc":"主屋の西に位置し、月江寺参道に面して建つ一間一戸の腕木門。起り付きの切妻造鉄板葺。主柱間に冠木を渡し、絵様付き腕木で軒桁を支え、軒は二軒疎垂木。門口には引違の板戸とし、欄間に梅の透彫を入れて飾る。主屋とともに料亭の華やかさを伝える脇門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014808"},{"id":"00014801","register_sub_id":"101","register_pk":"519059","name":"旧松亭蔵座敷","kana":"きゅうしょうていくらざしき","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県甲府市中央三丁目263-1他","lat":35.66132222,"lng":138.57487222,"geo_status":"db","era":"大正7年／令和3年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積37㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0172","desc":"甲府旧城下の魚町通りに位置するかつての料亭の座敷。敷地中央に位置する寄棟造桟瓦葺の東西棟で、外壁は塗込めて黒漆喰仕上、基礎廻りをモルタル塗仕上。戸口を西に設け、内部は一室の畳敷で東面に床を構え、黒檀の框など吟味した材を用いた蔵座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014801"},{"id":"00014802","register_sub_id":"101","register_pk":"519060","name":"旧松亭土蔵","kana":"きゅうしょうていどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲府市中央三丁目263-1他","lat":35.66128889,"lng":138.57500278,"geo_status":"db","era":"明治44年／令和元年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積129㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0173","desc":"蔵座敷の東に位置するかつての家財蔵。二階建寄棟造東西棟の南に寄棟造の南北棟を延ばし全体でＬ字を呈す。南西面に矩折れに下屋を付し外壁は漆喰塗仕上で二段の水切を廻らす。小屋組はトラス組。入隅に戸口と窓が並んだ特徴ある外観が、地域の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014802"},{"id":"00013537","register_sub_id":"101","register_pk":"504904","name":"旧堀田古城園主屋","kana":"きゅうほったこじょうえんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-1他","lat":35.68523889,"lng":138.57735,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積179㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0157","desc":"甲府市街北部、国指定史跡の武田氏館跡の指定地内に所在。平屋建寄棟造桟瓦葺。玄関両脇に室をおき、廊下を挟んで神棚付続き間、座敷を矩折れに並べ、南脇に離れ座敷を突出する。庭に面してガラス戸を建て、たちが高く開放的な外観を持つ近代和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013537"},{"id":"00013538","register_sub_id":"101","register_pk":"504905","name":"旧堀田古城園北離れ","kana":"きゅうほったこじょうえんきたはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-1","lat":35.68516667,"lng":138.57746111,"geo_status":"db","era":"昭和8年／平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0158","desc":"主屋の奥に南離れ、茶室とともに三棟並んで建つ。平屋建寄棟造鋼板葺で、六畳大座敷を主体とした独立建物。真壁造で庭側をガラス窓とし開放的な外観をつくる。建具の一部に金唐紙を用い、床脇を地袋天袋とするなど瀟洒な意匠を持つ。敷地の一角を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013538"},{"id":"00013542","register_sub_id":"101","register_pk":"504909","name":"旧堀田古城園木戸門","kana":"きゅうほったこじょうえんきどもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-1","lat":35.68535833,"lng":138.57732778,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0162","desc":"敷地北西隅に通りに面して建つ。切妻造桟瓦葺の木戸門で、前後に控えの柱を立てる。門柱は角柱で、挿肘木と斗で腕木を受け、軒桁を架ける。柱間は引違いの格子戸を建て「堀田古城園」の扁額を掲げる。武田氏の居館跡にある旧料亭旅館の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013542"},{"id":"00013540","register_sub_id":"101","register_pk":"504907","name":"旧堀田古城園茶室","kana":"きゅうほったこじょうえんちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-2","lat":35.685025,"lng":138.57740833,"geo_status":"db","era":"昭和8年／平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0160","desc":"敷地南東隅に北離れ、南離れとともに独立して建つ。平屋建寄棟造鋼板葺。真壁造で一見して北と南の離れと同様の意匠だが、菱形の平面の四畳半をつくるなど独特な形式を持つ。地袋と琵琶棚を並べて床構えとする等、小規模ながら数寄屋趣味が横溢する佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013540"},{"id":"00013541","register_sub_id":"101","register_pk":"504908","name":"旧堀田古城園長屋","kana":"きゅうほったこじょうえんながや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-1","lat":35.68531944,"lng":138.57743889,"geo_status":"db","era":"昭和8年／平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0161","desc":"敷地の北面に木戸門の東に建つ。平屋建寄棟造桟瓦葺。物置等として、数室に区画されていたが現在は二室とする。活用のため東面の一部や間仕切撤去等の改修はあるが、主要材は当初を残し真壁造の外観も踏襲する。木戸門とともに敷地北辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013541"},{"id":"00013539","register_sub_id":"101","register_pk":"504906","name":"旧堀田古城園南離れ","kana":"きゅうほったこじょうえんみなみはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-2","lat":35.68510278,"lng":138.57743333,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0159","desc":"主屋の奥に北離れ、茶室とともに三棟並んで建つ。平屋建寄棟造鋼板葺で、六畳大座敷を主体とした独立建物。真壁造で庭側をガラス窓とし開放的な外観をつくる。床構えなど細部意匠を含めて北離れと同規模同形式の設えとする。敷地東辺の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013539"},{"id":"00000431","register_sub_id":"101","register_pk":"101421","name":"松寿軒長崎","kana":"しょうじゅけんながさき","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南アルプス市荊沢319 他","lat":35.58896722,"lng":138.46596336,"geo_status":"db","era":"昭和1","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積102㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"19 － 0024","desc":"和菓子づくりを営む家の店舗。韮崎から下諏訪へと通じる国道５２号線（富士川街道）が鍵の手に曲がる場所に位置する。寄棟造，平入の土蔵造町家で，軒先を持送状に３段に重ねるなど重厚な外観を持つ。街道の要所に建つ老舗として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000431"},{"id":"00012360","register_sub_id":"101","register_pk":"531684","name":"大市館","kana":"だいいちかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町下部48","lat":35.42244444,"lng":138.48183056,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建、瓦葺、建築面積450㎡","structure_material":"木造3階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-136","desc":"下部温泉の中心部に東面して建つ旅館。木造三階建、入母屋造桟瓦葺で、正面北端に入母屋の玄関を設ける。一階に食堂、二、三階に大小一二の客室を配し、窓には刎高欄の手摺を付ける。下部川にかかる神泉橋のたもとにあって温泉街の景観に趣を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012360"},{"id":"00011496","register_sub_id":"101","register_pk":"210459","name":"中村屋旅館本館","kana":"なかむらやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲州市塩山上於曽1225","lat":35.70848806,"lng":138.73008111,"geo_status":"db","era":"大正6年頃／昭和10年頃改修、昭和30年頃増築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0091","desc":"塩山温泉に位置する。木造二階建、寄棟造、桟瓦葺。南正面中央に入母屋造の玄関が付き、二階正側面の小庇は吹寄せ垂木の瀟洒な意匠を見せる。玄関の天井は棹縁を扇形に配る特徴的なもので、二階の座敷は窓を多くとって開放的な造りとする。近代和風旅館の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011496"},{"id":"00012336","register_sub_id":"101","register_pk":"531660","name":"萩原家住宅西座敷","kana":"はぎはらけじゅうたくにしざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66121389,"lng":138.73105833,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"西店舗の奥に接続する。平屋建、切妻造の東西棟で、妻面を白漆喰で塗籠める。中央に土間を通して東に居室、西に座敷二室を配し、後方の西蔵との間にクジョウノマが突出する。それぞれ意匠の異なる造作で仕上げた座敷が近世商家の暮らしぶりを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012336"},{"id":"00012335","register_sub_id":"101","register_pk":"531659","name":"萩原家住宅西店舗","kana":"はぎはらけじゅうたくにしてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66129444,"lng":138.73108056,"geo_status":"db","era":"江戸末期／平成24年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積86㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"東店舗兼主屋の西側に並び建つ。木造二階建、切妻造の東西棟で、正面に下屋を通す。奥行は三間と狭く、一階をミセとし、二階に座敷を設ける。正面の面格子、揚戸や大戸などの構えがよく残り、東店舗兼主屋とともに連続性のある旧宿場の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012335"},{"id":"00012337","register_sub_id":"101","register_pk":"531661","name":"萩原家住宅西蔵","kana":"はぎはらけじゅうたくにしのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66110278,"lng":138.73098611,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"敷地の南奥に建つ。土蔵造二階建、切妻造の南北棟で、東面と北面に戸口を開き、下屋を廻す。一階は一四畳一間で座敷飾を備え、庭に面した南面にも観音扉の窓を開く。東面下屋の北端には便所も備える。床柱に珍木を用いるなど、随所に趣向を凝らす蔵座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012337"},{"id":"00012333","register_sub_id":"101","register_pk":"531657","name":"萩原家住宅東店舗兼主屋","kana":"はぎはらけじゅうたくひがしてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66124722,"lng":138.73124167,"geo_status":"db","era":"江戸末期／昭和45年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、金属板葺、建築面積204㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"旧甲州街道勝沼宿にあり、通りに北面して建つ。木造二階建、切妻造の東西棟で、正面に下屋、背面に張出しを設ける。東に一間半幅の土間を通し、床上部は二列構成とし、上手奥に座敷を配する。発展した平面形式をもち、繊細な格子で意匠を整えた大規模な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012333"},{"id":"00012334","register_sub_id":"101","register_pk":"531658","name":"萩原家住宅東蔵","kana":"はぎはらけじゅうたくひがしのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66118889,"lng":138.73140278,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積104㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"東店舗兼主屋の土間側に建つ、いわゆる蔵座敷。土蔵造二階建、切妻造の南北棟で、南に渡廊下を介し便所や浴室を設ける。一階は一二畳半の座敷二室で、座敷飾を備える。通りに面した北妻面には、庇付の観音扉の窓を上下に開き、重厚な街路景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012334"},{"id":"00003085","register_sub_id":"101","register_pk":"104075","name":"村松家住宅商家蔵","kana":"むらまつけじゅうたくしょうかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南アルプス市桃園615-1","lat":35.625549,"lng":138.464554,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"19 － 0042","desc":"駿信往還に東面して建つ。桁行８間梁間２間半の東面に５尺幅の下屋庇を付け，西面の南寄りに観音扉を開けて主屋土間に連絡する。貸付業開業時の店蔵とされ，北半を商品蔵，南半１階を店，同２階を居室とする。棟札から棟梁「夜子沢村幡野宗兵衛」が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003085"},{"id":"00016370","register_sub_id":"101","register_pk":"536437","name":"山口家住宅（𠮷田屋）表門","kana":"やまぐちけじゅうたく（よしだや）おもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県富士吉田市中曽根一丁目3843-1","lat":35.48400833,"lng":138.79864444,"geo_status":"db","era":"明治後期／昭和27年移築、平成13年改修、同21年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0186","desc":"御師住宅の連なる富士みちに西面して建つ旧旅館の表門。一間薬医門、切妻造瓦棒銅板葺で、重厚な板戸を両開きに吊る。幅一尺の主柱同士を冠木で固め、控柱上の桁との間に断面矩形の梁を三筋架ける。軸部木太く質実なつくりで富士みちのランドマークとなる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016370"},{"id":"00012531","register_sub_id":"101","register_pk":"367826","name":"相澤商店店舗","kana":"あいざわしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市中央二丁目4633","lat":36.399529,"lng":138.255493,"geo_status":"geocoded","era":"昭和10年／平成9年移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、銅板葺、建築面積157㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0534","desc":"市中心部にある商家で、店舗は敷地中央部に西面して建つ。土蔵造二階建、寄棟造銅板葺で、正面に下屋を通す。伝統的な和風意匠を基調に、下屋軒下のアカンサスの浮彫や腰壁のスクラッチタイル張などの洋風意匠を加味する。昭和前期の気風を伝える町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012531"},{"id":"00006431","register_sub_id":"101","register_pk":"107414","name":"飯島商店作業所棟","kana":"いいじましょうてんさぎょうしょとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市中央1-1-21","lat":36.3982057,"lng":138.24987089,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造3階建、瓦葺、建築面積330㎡","structure_material":"木造3階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0319","desc":"店舗の西方に東西棟で建つ。もと上田倉庫会社創業時の繭倉で、桁行２０間、梁間５間と長大。切妻造、桟瓦葺の木造３階建で、外壁は漆喰仕上げ。内部棟通りに３間間隔に柱を建て、大引を方杖で支える。小屋組はキングポストトラス。蚕都上田の繁栄を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006431"},{"id":"00006432","register_sub_id":"101","register_pk":"107415","name":"飯島商店事務所棟","kana":"いいじましょうてんじむしょとう","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市中央1-1-21","lat":36.398197,"lng":138.249573,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造3階建、瓦葺、建築面積231㎡","structure_material":"木造3階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0318","desc":"店舗棟の西方、角地に南北棟で建つ。もと上田倉庫会社創業時の繭倉で、桁行１４間、梁間５間規模の木造３階建。外壁は大壁で、漆喰仕上げ。切妻造、桟瓦葺とし、棟通りに３間間隔に柱を建てる。一部切り縮められているが、蚕都上田の発展を物語る施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006432"},{"id":"00006430","register_sub_id":"101","register_pk":"107413","name":"飯島商店店舗棟","kana":"いいじましょうてんてんぽとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市中央1-1-21","lat":36.39811785,"lng":138.25018718,"geo_status":"db","era":"大正13／昭和38頃曳家","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積146㎡","structure_material":"木造3階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0317","desc":"上田駅前からの通りに東面して建つ。正面１５ｍ、奥行１０ｍ、寄棟造、鉄板葺、木造３階建の洋風店舗事務所。外部はモルタル塗で石目地を切り、上部に櫛形飾り付のパラペットを廻す。小屋組はキングポストトラス。縦長窓が並ぶ整然とした意匠でまとめられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006430"},{"id":"00008113","register_sub_id":"101","register_pk":"132511","name":"大塚魚店旧店舗兼主屋","kana":"おおつかうおてんきゅうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県小諸市本町2-70","lat":36.32913365,"lng":138.42423865,"geo_status":"db","era":"江戸末期／明治後期・大正後期・昭和中期・平成18年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積224㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"20 － 0356","desc":"小諸城下の東西の通りに北面して建つ。間口１４ｍの木造２階建、東西棟の切妻造桟瓦葺で、正面に下屋庇を付ける。道路に面した北半部を店舗として開き、南半部は東側の通り土間と居室空間となる。登梁の鼻先を延ばし軒桁を支持するなど、伝統的な表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008113"},{"id":"00010282","register_sub_id":"101","register_pk":"199055","name":"越志家住宅主屋（旧廣善院客殿）","kana":"おしけじゅうたくしゅおく（きゅうこうぜんいんきゃくでん）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市戸隠字宝光社2332","lat":36.730986,"lng":138.076759,"geo_status":"db","era":"江戸後期／明治34年・平成5年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅葺、建築面積252㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0459","desc":"戸隠の宿坊廣善院のもと客殿で、寄棟造茅葺である。中央奥に神殿を南面させ、手前二室を道場として玄関を構える。西列に座敷、東列に居室を配する。明治後期に祭壇を仏式から神式へ改めるなどの改修を受けており、宿坊の変容過程や戸隠信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010282"},{"id":"00010283","register_sub_id":"101","register_pk":"199056","name":"越志家住宅土蔵","kana":"おしけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市戸隠字宝光社2332","lat":36.73095,"lng":138.076956,"geo_status":"db","era":"明治中期／昭和40年頃移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0460","desc":"主屋の東方に建つ二階建の土蔵。置屋根式鉄板葺で西面に下屋を設ける。外壁漆喰塗で、腰を簓子下見板張とし、丑鼻に付した家紋や窓枠を鏝絵細工で飾る。もとは一階に食料を、二階に家財を収めていたという土蔵で、戸隠の宿坊における生活様態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010283"},{"id":"00005147","register_sub_id":"101","register_pk":"106137","name":"かどや商店店舗","kana":"かどやしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市松代町松代701","lat":36.56712621,"lng":138.20139142,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0215","desc":"東面する道路に接して建つ。桁行５間，梁間３間半の規模で，切妻造，桟瓦葺の木造２階建。正面に下屋を張出し真壁造とするが，妻破風から側壁，隅柱上の垂木までを漆喰で塗込める。町人町の往時の様子を伝える商家として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005147"},{"id":"00009016","register_sub_id":"101","register_pk":"162376","name":"金具屋別館臨仙閣本館","kana":"かなぐやべっかんりんせんかくほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏2147-1","lat":36.73419131,"lng":138.43203138,"geo_status":"db","era":"昭和4年／昭和15年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造3階地下1階建、鉄板葺、建築面積303㎡","structure_material":"木造3階地下1階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0413","desc":"川沿いの通りに南面する。Ｌ字型棟の入母屋造鉄板葺、木造三階地下一階建、建築面積３０３㎡。各階に連続窓を開き、庇や縁を付けて重層的な外観とする。内部は二階の赤壁や磨丸太、三階の海鼠壁や漆喰壁など仕様を大きく違え、変化に富む構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009016"},{"id":"00009017","register_sub_id":"101","register_pk":"162377","name":"金具屋別館臨仙閣浴堂","kana":"かなぐやべっかんりんせんかくよくどう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏2145-3他","lat":36.7341578,"lng":138.4321924,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0414","desc":"臨仙館本館の東に小路を挟んで建つ。東西棟の切妻造鉄板葺で、棟際に煙出風の小屋根、南北に下屋を付設する。木造平屋建、建築面積７５㎡。中廊下で男女の浴室を南北に分ける。円柱に虹梁、皿斗付大斗肘木や叉首組など仏堂風意匠の大浴場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009017"},{"id":"00003430","register_sub_id":"101","register_pk":"104420","name":"金具屋旅館大広間","kana":"かなぐやりょかんおおひろま","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏2202","lat":36.73510228,"lng":138.43266379,"geo_status":"db","era":"昭和11／昭和25改築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積322㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0137","desc":"斉月楼と同時に建設された１７０畳の大広間。一時大雪のため屋根を大きく傷めたが，昭和２５年に修復されている。外観は斉月楼と比較して簡素な意匠とするが，内部の折り上げ格天井など見るべきものがある。木造和風旅館建築の大広間の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003430"},{"id":"00014604","register_sub_id":"101","register_pk":"515146","name":"軽井沢新スタジオ（旧アントニン・レーモンド軽井沢別邸）主屋","kana":"かるいざわしんすたじお","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県北佐久郡軽井沢町大字長倉字広原21-10","lat":36.323125,"lng":138.62328889,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積146㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"20 - 0632","desc":"軽井沢の南方に建つアントニン・レーモンド晩年の別荘兼事務所。一二角形平面の居間・食堂兼スタジオを中心に、西に厨房等、東に寝室と和室を付す。居間・食堂は煙突付暖炉を中心に唐傘形に丸太の梁組を架ける。設計者の丸太を用いた作風の円熟期を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014604"},{"id":"00015183","register_sub_id":"101","register_pk":"530607","name":"旧犬飼呉服店店舗兼主屋","kana":"きゅういぬかいごふくてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市大手四丁目1244-イ","lat":36.23622778,"lng":137.97416944,"geo_status":"db","era":"昭和前期／令和5年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積87㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0659","desc":"松本城南東、善光寺街道の角地に建つ旧呉服店の町家。土蔵造二階建、正面はモルタル洗出仕上に目地を入れ石造風、側面などを漆喰塗仕上。一階は通り土間沿いに部屋を一列に並べ、二階に端正な床構え付き座敷を配す。石造風外観が街路景観の近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015183"},{"id":"00015184","register_sub_id":"101","register_pk":"530608","name":"旧犬飼呉服店土蔵","kana":"きゅういぬかいごふくてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市大手四丁目1244-イ","lat":36.23621111,"lng":137.974225,"geo_status":"db","era":"明治6年","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積23㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0660","desc":"主屋の背後に建つ家財蔵。妻入の土蔵造二階建で、正面一・二階に銅板葺庇を付ける。内部は各階一室の板敷で、二階に豪壮な梁組を現す。外壁は白漆喰塗で腰海鼠壁とし、正面二階中央に掛子塗扉を付した窓を開く。重厚かつ均整のとれた外観で屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015184"},{"id":"00015018","register_sub_id":"101","register_pk":"529296","name":"旧小澤家住宅（油屋）表門","kana":"きゅうおざわけじゅうたく（あぶらや）おもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡辰野町大字小野字町975-1","lat":36.04188333,"lng":137.96864167,"geo_status":"db","era":"江戸末期／昭和50年代改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、鉄板葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0657","desc":"主屋の北に位置し、通りに東面する一間一戸切妻造鉄板葺の薬医門。南北に袖塀を付し、南に潜戸を設ける。主柱に渡した冠木上に三筋の男梁を架け、正面側は先端に実肘木付平三斗を置き丸桁を支持、梁中央は蟇股を飾る。勇壮な構えで旅籠の格式を伝える表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015018"},{"id":"00015017","register_sub_id":"101","register_pk":"529295","name":"旧小澤家住宅（油屋）主屋","kana":"きゅうおざわけじゅうたく（あぶらや）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡辰野町大字小野字町975","lat":36.0418,"lng":137.96845278,"geo_status":"db","era":"万延2年（1861）／昭和50年代改修","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積276㎡","structure_material":"木造平屋一部2階建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0656","desc":"三州街道の小野宿北寄りに位置し、かつて旅籠を営んだ主屋。通りに東面する切妻造妻入鉄板葺の本棟造で、棟頂部に雀踊りを飾る。正面南側は土間と旧のウマヤを配し、北側は式台を設け、西に三間続きの座敷を配す。広い式台玄関が格式を示す規模雄大な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015017"},{"id":"00013249","register_sub_id":"101","register_pk":"366238","name":"旧小諸脇本陣主屋","kana":"きゅうこもろわきほんじんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県小諸市市町一丁目18","lat":36.33002778,"lng":138.42053333,"geo_status":"db","era":"江戸末期／平成31年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積275㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"20 － 0560","desc":"小諸宿脇本陣とされる旅籠の主屋で、北国街道に南面して建つ。木造二階建、切妻造桟瓦葺平入で、背面に別棟の渡廊下や水回りが付く。正面は一階西側に大きな切妻屋根の式台を設け、二階東側は手摺を廻した縁とする。本陣と共に近世宿場町の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013249"},{"id":"00013251","register_sub_id":"101","register_pk":"366240","name":"旧小諸脇本陣土蔵","kana":"きゅうこもろわきほんじんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県小諸市市町一丁目18","lat":36.32991389,"lng":138.42051389,"geo_status":"db","era":"明治前期／平成31年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"20 － 0562","desc":"離座敷の東側に主屋の渡廊下を介して建つ。土蔵造二階建、切妻造桟瓦葺妻入で、南面に戸口を開く。外壁は白漆喰塗で、鉢巻を廻らす。内部は一、二階とも板敷の一室で、二階は南面と東面に窓を配す。もとは家財道具を収めた蔵で、屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013251"},{"id":"00013250","register_sub_id":"101","register_pk":"366239","name":"旧小諸脇本陣離座敷","kana":"きゅうこもろわきほんじんはなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県小諸市市町一丁目18","lat":36.32937083,"lng":138.42122694,"geo_status":"db","era":"江戸末期／平成31年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺一部金属板葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"20 － 0561","desc":"南北に長い敷地の中央西側で、主屋の渡廊下に接続して建つ。木造平屋建、切妻造桟瓦葺の南北棟で、南面と北面に下屋を付す。内部は田字形に四室配し、八畳の主座敷には床、棚、書院を備える。宿場町の脇本陣において、往時の様相を今に伝える建物の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013250"},{"id":"00006428","register_sub_id":"101","register_pk":"107411","name":"旧信濃中牛馬合資会社社屋","kana":"きゅうしなのちゅうぎゅうばごうしがいしゃしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字長野大門町67-1","lat":36.656536,"lng":138.187668,"geo_status":"db","era":"明治45／大正13頃曳家","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造2階一部平屋建、瓦葺、建築面積98㎡、門付","structure_material":"煉瓦造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0315","desc":"善光寺の門前、大門町中央通りに西面して建つ運送会社の社屋。間口７．４ｍ、奥行９．３ｍの煉瓦造２階建で、屋根は切妻造、桟瓦葺とし屋根窓をのせる。正面は施釉煉瓦に花崗岩を要所に配する。目地仕上げなど施工も丁寧。善光寺門前の町並みの近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006428"},{"id":"00006429","register_sub_id":"101","register_pk":"107412","name":"旧第一勧業銀行松本支店","kana":"きゅうだいいちかんぎょうぎんこうまつもとしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市大手3-70-5","lat":36.235939,"lng":137.969574,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下1階建、建築面積692㎡、塔屋付","structure_material":"鉄筋コンクリート造3階一部地下1階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0316","desc":"松本城に向かう通りに東面して建つ。鉄筋コンクリート造３階建一部地下室及び塔屋付で、営業室は吹抜けの大空間とする。外壁はモルタル塗で石目地を切る。独特の曲線形状になるアーチの開口を正面に７連、両側面と背面に各３連開け、外観を特色づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006429"},{"id":"00008283","register_sub_id":"101","register_pk":"133925","name":"旧光屋店舗兼主屋","kana":"きゅうひかるやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市大手4-1169-2","lat":36.23536109,"lng":137.97370731,"geo_status":"db","era":"明治20年／平成7年移築・平成19年改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積258㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0366","desc":"旧善光寺街道に東面して建つ、間口１５ｍに及ぶ大型の町家。木造２階建。正背面に下屋を設け、奥行は１８ｍ。外壁は大壁造で、正面上屋には掛子塗両開戸を吊る窓を六ヶ所開ける。腰は海鼠壁とする。座敷構えや欄間など、意匠、材料ともに洗練されたものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008283"},{"id":"00008284","register_sub_id":"101","register_pk":"133926","name":"旧光屋文庫蔵","kana":"きゅうひかるやぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県松本市大手4-1169-1他","lat":36.23549278,"lng":137.97365923,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積17㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0367","desc":"店舗兼主屋の西北に位置する。東西棟の切妻造桟瓦葺。桁行４．５ｍ梁間３．６ｍの２階建土蔵。切石基礎とし、外壁は漆喰仕上げで腰を海鼠壁とする。南面やや西寄りに出入口を開け、掛子塗の両開戸を吊る。拝み部分に「光」をあしらい、建物の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008284"},{"id":"00009600","register_sub_id":"101","register_pk":"194596","name":"旧伏見屋北土蔵","kana":"きゅうふしみやきたどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県諏訪郡下諏訪町字原東521-1他","lat":36.07990597,"lng":138.08532916,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0431","desc":"敷地の北西に位置し、桁行梁間とも三・六メートル、土蔵造二階建、切妻造置屋根式の鋼瓦葺で、主屋側に下屋と戸口を設ける。街道側の腰を海鼠壁とし、上部に観音扉の窓および庇を設け意匠性を高める。呉服蔵として使用されたと伝わり、街道側の景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009600"},{"id":"00009598","register_sub_id":"101","register_pk":"194594","name":"旧伏見屋店舗兼主屋","kana":"きゅうふしみやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県諏訪郡下諏訪町字原東521-1","lat":36.07982269,"lng":138.0854868,"geo_status":"db","era":"元治元／平成22改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造2階建、銅板葺、建築面積144㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0429","desc":"諏訪大社下社春宮と秋宮を結ぶ旧中山道に面して建つ。木造二階建で通土間を有した町家形式の建築で、通りに面して上店、下店を、背面には座敷と縁を配す。一階正面には出格子をたて摺上戸を設ける。参詣道として賑わった街道沿いの商家の佇まいを良好に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009598"},{"id":"00009599","register_sub_id":"101","register_pk":"194595","name":"旧伏見屋南土蔵","kana":"きゅうふしみやみなみどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県諏訪郡下諏訪町字原東521-1他","lat":36.07984351,"lng":138.0852905,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0430","desc":"敷地の南西に位置し、桁行六・四メートル梁間三・九メートル、土蔵造二階建、切妻造置屋根式の鋼瓦葺で、主屋側に下屋を設ける。外壁は漆喰塗で、南面は腰を簓子下見板張とする。家財等の収納に使用された土蔵で、店舗兼主屋とともに商家の構えを引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009599"},{"id":"00005829","register_sub_id":"101","register_pk":"106815","name":"旧三河屋商店店舗兼住宅","kana":"きゅうみかわやしょうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字長野東町165-3","lat":36.655724,"lng":138.189087,"geo_status":"db","era":"江戸後期／平成8曳家","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積169㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0260","desc":"油問屋の店舗兼住宅として建築。２階建，塗屋造の町家で，間口９間，奥行４間半の切妻造，桟瓦葺，平入の表に１間幅の庇がつく。正面１階中央が戸口で，左手は庇下を室内に取り込む。１階は中央が通り土間で左右を居室とし，２階に２４畳広間と居室を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005829"},{"id":"00016384","register_sub_id":"101","register_pk":"536451","name":"旧矢﨑商店店舗兼主屋","kana":"きゅうやざきしょうてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪郡下諏訪町字塚田3156-19","lat":36.07699722,"lng":138.08676944,"geo_status":"db","era":"昭和11年／昭和20年改修、同30年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、桟瓦葺一部鉄板葺、建築面積156㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0678","desc":"御田町通りの中心部に西面して建つ、旧生糸問屋の店舗兼主屋。木造二階建で正面側はモルタル洗出仕上、腰タイル貼の立体感ある看板建築でアールデコ調の外観とするが、背面側は桟瓦葺で、和風の座敷を張出すなど対照的。戦後の下諏訪の繁栄を伝える看板建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016384"},{"id":"00016386","register_sub_id":"101","register_pk":"536453","name":"旧矢﨑商店納屋","kana":"きゅうやざきしょうてんなや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪郡下諏訪町字塚田3156-19","lat":36.07705556,"lng":138.08693889,"geo_status":"db","era":"昭和前期／昭和30年頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋一部2階建、鉄板葺、建築面積13㎡","structure_material":"木造平屋一部2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0680","desc":"店舗兼主屋の北東に位置する味噌蔵兼物置。不整形平面の平屋一部二階建、片流屋根瓦棒鉄板葺。外壁モルタル洗出仕上、腰は独特な自然石貼。内部は隅柱や落し込み板の最下段にクリを用いる。頂部にパラペットを廻らした洋風の独特な外観が主屋と呼応する納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016386"},{"id":"00016385","register_sub_id":"101","register_pk":"536452","name":"旧矢﨑商店文庫蔵","kana":"きゅうやざきしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪郡下諏訪町字塚田3156-19","lat":36.07698611,"lng":138.08695833,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0679","desc":"店舗兼主屋の南東に西面して建つ文庫蔵。土蔵造二階建切妻造桟瓦葺。外壁漆喰塗、腰海鼠壁仕上で、蔵前は柱や桁に丸太を用いる。内部は柱に横板を落し込み、柱や最下段の壁板にクリを用いる。小屋組はトラス。階段下に棚を造作するなど丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016385"},{"id":"00014371","register_sub_id":"101","register_pk":"511360","name":"旧料亭信濃離れ菊の間","kana":"きゅうりょうていしなのはなれきくのま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県諏訪市大手二丁目3008-1他","lat":36.04295,"lng":138.11704722,"geo_status":"db","era":"大正前期／昭和中期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0616","desc":"上諏訪駅の南に位置する料亭離れ。平屋建入母屋造桟瓦葺の東西棟で北面し、内部は東を寄付、西を八畳座敷とし、南面に縁を付して水屋と便所に連絡する。床や書院、窓廻りや天井に多様な竹を散り嵌め、細部まで技巧を凝らす。煎茶趣味が溢れる数寄屋風の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014371"},{"id":"00014372","register_sub_id":"101","register_pk":"511361","name":"旧料亭信濃離れ桐の間","kana":"きゅうりょうていしなのはなれきりのま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県諏訪市大手二丁目3008-1他","lat":36.04299167,"lng":138.116975,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0617","desc":"上諏訪駅の南に位置する料亭離れ。平屋建入母屋造桟瓦葺の南北棟で東面し、内部は北の玄関から取次ぎの間を通って十畳の座敷に至る。座敷の畳床と両脇床の構成は近代らしい。銘木や竹をふんだんに用い、内外に渡り技巧を凝らした上質な造りの数寄屋風の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014372"},{"id":"00005851","register_sub_id":"101","register_pk":"106837","name":"杭全家住宅主屋","kana":"くまたけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代635","lat":36.565125,"lng":138.201859,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積166㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0274","desc":"松代城下，旧谷街道に西面して建つ商家。桁行７間，梁間２間半の塗屋造２階建，切妻造，桟瓦葺。表に下屋を付け，玄関，便所を配す。内部は南半がもと土間，北半を居室とし，背面の角屋まで１２畳半３室を並べる。２階正面など簡素であるが重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005851"},{"id":"00014374","register_sub_id":"101","register_pk":"511363","name":"栗林家住宅（創舎わちがい）店舗","kana":"くりばやしけじゅうたく（そうしゃわちがい）てんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県大町市大町4084-1他","lat":36.50513056,"lng":137.85910833,"geo_status":"db","era":"大正後期／平成17年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0619","desc":"大町の中心市街地で、通りに西面する庄屋の町家。切妻造平入桟瓦葺、真壁造漆喰仕上、正面に格子戸を建て、南側を通り土間とし、北側を表から前土間、ミセ、オエ、カッテを並べる。通りに面し二階に床付座敷を配し、窓を設け、歴史的な町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014374"},{"id":"00011692","register_sub_id":"101","register_pk":"210708","name":"寿高原食品四階倉庫","kana":"ことぶきこうげんしょくひんよんかいそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県千曲市大字戸倉字大明神1465-1","lat":36.491697,"lng":138.152688,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造4階建、瓦葺、建築面積318㎡","structure_material":"土蔵造4階建","registered":"2017.06.28(平成29.06.28)","register_no":"20-0510","desc":"戸倉駅前に建つ桁行二九メートル、梁間一一メートル、土蔵造の大規模倉庫。三階までは中央二間毎に六寸柱を立て大梁で固め、四階は柱を立てず大空間とする。小屋組はキングポストトラス。方杖付の庇を持つ窓を一間置きに開く多窓式の外観で地域景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011692"},{"id":"00008457","register_sub_id":"101","register_pk":"134853","name":"小林家住宅主屋","kana":"こばやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字宗賀字本山4917他","lat":36.06116593,"lng":137.9011553,"geo_status":"db","era":"明治前期／明治期改修・昭和34年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積146㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"20 － 0370","desc":"旧本山宿に所在し、中山道に東面する。桁行一二メートル梁間九・九メートルの木造二階建、切妻造鉄板葺。二階全面に千本格子を通し、両端に袖ウダツを設け、一階に式台を構える。類例の少ない二重出梁を残す。三棟の平入町家が連続して残り、宿場の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008457"},{"id":"00005816","register_sub_id":"101","register_pk":"106803","name":"小諸市北国街道ほんまち町屋館","kana":"こもろしほっこくかいどうほんまちまちやかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県小諸市本町2-2-9","lat":36.329369,"lng":138.423676,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0298","desc":"旧北国街道沿いの商家で，桁行７間半，梁間６間の規模で，木造２階建，切妻造，桟瓦葺とする。２階通り側に２０畳の座敷を設け，裏側に８畳間２室を並べる。側面及び２階軒裏を塗り込め，漆喰塗の鉢巻きを廻し，重厚な塗屋造の外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005816"},{"id":"00003091","register_sub_id":"101","register_pk":"104081","name":"笹屋ホテル別荘","kana":"ささやほてるべっそう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県千曲市上山田温泉1-1-1","lat":36.48370704,"lng":138.14180298,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積965㎡","structure_material":"木造2階一部平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0111","desc":"ホテル本館西方に建つ３棟と渡り廊下から成る客室群。遠藤新の設計になる木造和風旅館建築で，畳敷きの座敷と一段下げた椅子置きの広縁から庭に至る客室構成に遠藤新の作風が示されている。この構成は後の国際観光旅館等に大きな影響を与えたとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003091"},{"id":"00007633","register_sub_id":"101","register_pk":"108615","name":"塩尻短歌館","kana":"しおじりたんかかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県塩尻市大字広丘原新田288-1","lat":36.15272345,"lng":137.94507204,"geo_status":"db","era":"明治元／平成4移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積266㎡","structure_material":"木造平屋一部2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0350","desc":"敷地の南西隅、南面して建つ。桁行１３ｍ梁間１７ｍ、木造平屋一部２階建、切妻造妻入鉄板葺で、南面に式台と下屋を付ける。２階妻面に出格子を設け、破風板上に棟飾りの雀おどしを戴く。内部の間取や外観に、本棟造民家として整った形態をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007633"},{"id":"00006226","register_sub_id":"101","register_pk":"107210","name":"塩屋醸造店舗及び主屋","kana":"しおやじょうぞうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.65588425,"lng":138.31577575,"geo_status":"db","era":"明治初期／昭和27改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋一部2階建、瓦葺、建築面積210㎡","structure_material":"木造平屋一部2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0302","desc":"市道沿いに北面して建つ。間口６間，奥行１１間規模，木造平屋一部２階建，切妻造，桟瓦葺。通りに面して平入の店舗を置き，奥に居住部分を配する。正面に下屋を付け，２階壁や軒廻り等を塗り込む。大規模な商家の外観を持ち，街路沿いの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006226"},{"id":"00010781","register_sub_id":"101","register_pk":"201616","name":"須高農業協同組合井上支所","kana":"すこうのうぎょうきょうどうくみあいいのうえししょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県須坂市大字幸高447-2","lat":36.638402,"lng":138.282958,"geo_status":"db","era":"昭和3／平成10改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、銅板葺、建築面積337㎡、塔屋付","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0493","desc":"左右対称の正面両端をやや張出してマンサード破風を設け、屋根上に小振りの塔屋とドーマー窓を配す。外壁はモルタル塗で大オーダーを表して垂直性を強調する。内部階段などに幾何意匠を用い、入口上部に「井上に産」を図案化して飾る。洋風意匠の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010781"},{"id":"00008456","register_sub_id":"101","register_pk":"134852","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字宗賀字本山4916-1","lat":36.06109619,"lng":137.90116145,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積152㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"20 － 0369","desc":"旧本山宿に所在し、中山道に東面する。桁行一二メートル梁間一二メートルの平入町家。切妻造鉄板葺とし、棟に越屋根を付ける。出梁造とし、二階全面に千本格子を通し、両端に袖ウダツを設け、一階に式台を構える。軸部は弁柄塗。華やかな旅篭の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008456"},{"id":"00000047","register_sub_id":"101","register_pk":"101037","name":"中央印刷社屋（旧片倉組事務所）","kana":"ちゅうおういんさつしゃおく（きゅうかたくらぐみじむしょ）","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県岡谷市川岸1-1-20","lat":36.05332844,"lng":138.03452726,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、銅板葺、建築面積335㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"20 － 0002","desc":"日本を代表する製糸業者であった片倉組の本社屋として建設され，その後系列会社に引き継がれて今日に至っている。人造石の柱型に煉瓦の壁面を組み合わせた外観や，洋風を基本に和風のモチーフを巧みに取り込んだ内部が特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000047"},{"id":"00008984","register_sub_id":"101","register_pk":"162344","name":"徳本峠小屋休憩所","kana":"とくごうとうげごやきゅうけいじょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県松本市安曇1743","lat":36.22813383,"lng":137.67830516,"geo_status":"db","era":"大正12年／平成22年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0381","desc":"松本盆地から上高地に至る山道の標高２１３４ｍの峠に建つ。木造平屋建、桁行５．５ｍ梁間５．１ｍ、切妻造石置板葺である。内部は板敷で一部を土間とする。近代登山の舞台となった北アルプスに開設された山小屋の初期形態をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008984"},{"id":"00003429","register_sub_id":"101","register_pk":"104419","name":"金具屋旅館斉月楼","kana":"なかぐやりょかんさいげつろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏2202","lat":36.73486613,"lng":138.43282459,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造4階建、鉄板葺、建築面積172㎡","structure_material":"木造4階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0136","desc":"湯田中・渋温泉の旅館建築。木造４階建，入母屋造，鉄板葺。昭和８年起工，同11年竣工で，内部は主として客室とする。外観・内装ともに数寄屋風の様々な意匠をちりばめ，細部も細かく造り分け，非日常的な空間を現出する，温泉旅館建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003429"},{"id":"00003088","register_sub_id":"101","register_pk":"104078","name":"中澤時計本店","kana":"なかざわとけいほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市大字長野大門町48-1","lat":36.655178,"lng":138.187576,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、銅板葺、建築面積158㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0108","desc":"市区改正による善光寺前中央通りの拡幅に際して建設。角地に位置し，善光寺に向けた北西面を隅切りとする。木造２階建，鉄網コンクリートの洗出仕上げで，細部意匠はセセッションの流れを汲む。設計は長野市嘱託建築技師の本田政蔵，施工は大工棟梁池田市郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003088"},{"id":"00010968","register_sub_id":"101","register_pk":"208938","name":"中野家住宅北土蔵","kana":"なかのけじゅうたくきたどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂字春木町421-1","lat":36.655865,"lng":138.312858,"geo_status":"db","era":"安政4（1857）","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0497","desc":"蔵座敷からさらに西に接続する。土蔵造二階建で、一階は南に出入口を、二階は東の蔵座敷からの出入口を設けて、動線を分ける。もとは一階に日用品、二階に家財道具などを収納したと伝わる。屋根は置屋根形式とし、蔵の多いことで知られる須坂の町を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010968"},{"id":"00010967","register_sub_id":"101","register_pk":"208937","name":"中野家住宅蔵座敷","kana":"なかのけじゅうたくくらざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂字春木町420","lat":36.655867,"lng":138.313009,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造3階建、瓦葺、建築面積90㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0496","desc":"下店から渡り廊下を介して西に接続する居住棟。木造三階建のたちの高い建物で、南に玄関を開く。一階は仏間を兼ねた接客用の続き間座敷とし、北面に床を構え、付書院を備える。二階と三階を寝室等として居住に用いる。須坂の大店の暮らしぶりを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010967"},{"id":"00010966","register_sub_id":"101","register_pk":"208936","name":"中野家住宅下店","kana":"なかのけじゅうたくしたみせ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂字春木町420","lat":36.655867,"lng":138.313184,"geo_status":"db","era":"明治中期／平成23改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積86㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0495","desc":"通りに東面して建つ。切妻造平入とし、正面を塗込めて土蔵造風とする。二階正面は黒漆喰塗として、出桁を設け、格子窓を穿って迫力を見せる。当初は一階にミセとチャノマを設ける。繊維で知られる須坂において、明治期の呉服店の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010966"},{"id":"00010969","register_sub_id":"101","register_pk":"208939","name":"中野家住宅南土蔵","kana":"なかのけじゅうたくみなみどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂字中町218","lat":36.655734,"lng":138.312977,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0498","desc":"上店の西方に接続して建つ。土蔵造二階建で、商品の呉服の在庫を保管するための蔵である。東に出入口を開き、両開とする掛子塗の厚い土戸を吊って、高い左官技術を見せる。小屋は和小屋で、置屋根形式として、当地の伝統的な土蔵の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010969"},{"id":"00008691","register_sub_id":"101","register_pk":"149412","name":"中房温泉板倉","kana":"なかぶさおんせんいたくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39464311,"lng":137.74709957,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0378","desc":"本館菊の東に位置する。東西棟の切妻造鉄板葺。桁行6.1ｍ梁間4.6ｍの木造平屋建。切石基礎上に土台をまわし、方柱を4間×3間にたて、横板を落とし込み板壁とする。桁や梁、母屋を架け、一軒疎垂木を配る。内部は東西2室に分ける。素朴な味わいをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008691"},{"id":"00008689","register_sub_id":"101","register_pk":"149410","name":"中房温泉温泉大プール","kana":"なかぶさおんせんおんせんだいぷーる","category":"産業3次","subcategory":"その他工作物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39391157,"lng":137.74620787,"geo_status":"db","era":"大正12年","year":1923,"year_source":"converted","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造、面積147㎡","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0376","desc":"温泉地の西南に位置する。温泉を用いた屋外プール。幅8.7ｍ長さ17ｍで、深さ1.2ｍを測る。周辺でとれる有明花崗岩を利用した切石を4段に積み上げ、壁面を造る。北・西・東の3方には階段2段が積まれる。近代的な温泉場の先駆けをなす施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008689"},{"id":"00008686","register_sub_id":"101","register_pk":"149407","name":"中房温泉旧湯会所","kana":"なかぶさおんせんきゅうゆかいしょ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39459245,"lng":137.7469195,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、板葺一部鉄板葺、建築面積46㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0373","desc":"本館菊の西南に位置する。東西棟の切妻造で、南側を石置板葺、北を鉄板葺とする。桁行6.4ｍ梁間6.4ｍの木造2階建。外壁は下見板張で、南面には窓を穿つ。1階は西半部を板敷、東寄りを部屋として間仕切る。木立を背景に石置屋根の特徴ある外観を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008686"},{"id":"00008687","register_sub_id":"101","register_pk":"149408","name":"中房温泉田村薬師堂","kana":"なかぶさおんせんたむらやくしどう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39436471,"lng":137.7464125,"geo_status":"db","era":"嘉永元年(1848)／昭和50年改修","year":1848,"year_source":"converted","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積4.5㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0374","desc":"温泉地の西方に位置する。正面1間、側・背面2間、宝形造鉄板葺。正面に引違い格子戸をたて、側・背面板壁。正・側三方に切目縁をまわす。円柱が直接に桁を支持し、軒天井を張る。内部は後半部に壇を構え、本尊を安置。温泉起源に関わる伝説を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008687"},{"id":"00008690","register_sub_id":"101","register_pk":"149411","name":"中房温泉土蔵","kana":"なかぶさおんせんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39462526,"lng":137.74715489,"geo_status":"db","era":"嘉永7年(1854)／明治期移築","year":1854,"year_source":"converted","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積14㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0377","desc":"本館菊の東南に位置する。南北棟とする切妻造鉄板葺で、桁行4.6ｍ梁間3.0ｍの木造二階建。方柱に横板を建て込む板蔵で、外壁には土を塗り上げたとみられる。西面中央を出入口とし、引込戸をたてる。山村に多くみられる特徴的な蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008690"},{"id":"00008685","register_sub_id":"101","register_pk":"149406","name":"中房温泉本館菊","kana":"なかぶさおんせんほんかんきく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39463572,"lng":137.74695204,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鉄板葺、建築面積123㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0372","desc":"有明山中腹に位置する温泉施設。東西棟の切妻造鉄板葺、桁行13ｍ梁間5.4ｍの木造2階建。西側に平屋建の浴場を付設。各階とも南側に縁を通し、4室の和室を配する。南面は全面を開放的に扱い、1階を掃き出し、2階を窓とする。近代の湯治場建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008685"},{"id":"00008688","register_sub_id":"101","register_pk":"149409","name":"中房温泉山の神の社","kana":"なかぶさおんせんやまのかみのやしろ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39434865,"lng":137.74636298,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、こけら葺、建築面積0.18㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0375","desc":"田村薬師堂の西に位置する。陰刻のある巨大な岩の上に鎮座する小祠。土台上に建つ1間社流造、こけら葺。身舎は円柱で貫や長押で固め、台輪上に三斗を組む。妻は虹梁大瓶束で、二軒繁垂木。庇は几帳面取方柱、三斗組。丁寧に仕上げられた小規模社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008688"}];
